/* Waveshare ESP32-S3-Touch-LCD-3.5 : ST7796 panel.
 * Uses NuttX ST7789 driver for framebuffer/pixel ops, but sends the ST7796
 * vendor init sequence ourselves (NuttX has no ST7796 driver, and the ST7789
 * default init does not turn the ST7796 pixels on).
 * SPDX-License-Identifier: Apache-2.0
 */
#include <nuttx/config.h>
#include <stdbool.h>
#include <stdint.h>
#include <debug.h>
#include <errno.h>
#include <syslog.h>

#include <nuttx/arch.h>
#include <nuttx/board.h>
#include <nuttx/signal.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/spi/spi.h>
#include <nuttx/lcd/lcd.h>
#include <nuttx/lcd/st7789.h>
#include <nuttx/ioexpander/ioexpander.h>
#include <nuttx/ioexpander/pca9557.h>

#include "esp32s3_i2c.h"
#include "esp32s3_spi.h"
#include "esp32s3_gpio.h"
#include "esp32s3-devkit.h"

#define LCD_SPI_PORTNO   2
#define LCD_I2C_PORTNO   0
#define TCA9554_ADDR     0x20
#define TCA9554_FREQ     100000
#define EXIO_PWR         0
#define EXIO_LCD_RST     1
#define GPIO_LCD_BL      6
#define LCD_W            320
#define LCD_H            480

static struct spi_dev_s *g_spidev;
static struct lcd_dev_s *g_lcd;
static struct pca9557_config_s g_tca9554 = { TCA9554_ADDR, TCA9554_FREQ, NULL };

struct st7796_cmd_s { uint8_t cmd; uint8_t len; uint8_t data[16]; uint16_t delayms; };

static const struct st7796_cmd_s g_st7796_init[] =
{
  {0x11, 0, {0}, 120},
  {0xF0, 1, {0xC3}, 0},
  {0xF0, 1, {0x96}, 0},
  {0x36, 1, {0x48}, 0},
  {0x3A, 1, {0x55}, 0},
  {0xB4, 1, {0x01}, 0},
  {0xB6, 3, {0x80, 0x02, 0x3B}, 0},
  {0xE8, 8, {0x40, 0x8A, 0x00, 0x00, 0x29, 0x19, 0xA5, 0x33}, 0},
  {0xC1, 1, {0x06}, 0},
  {0xC2, 1, {0xA7}, 0},
  {0xC5, 1, {0x18}, 0},
  {0xE0, 14, {0xF0,0x09,0x0B,0x06,0x04,0x15,0x2F,0x54,0x42,0x3C,0x17,0x14,0x18,0x1B}, 0},
  {0xE1, 14, {0xE0,0x09,0x0B,0x06,0x04,0x03,0x2B,0x43,0x42,0x3B,0x16,0x14,0x17,0x1B}, 0},
  {0xF0, 1, {0x3C}, 0},
  {0xF0, 1, {0x69}, 0},
  {0x21, 0, {0}, 0},
  {0x29, 0, {0}, 120},
};

static void st7796_wrcmd(struct spi_dev_s *spi, uint8_t cmd,
                         const uint8_t *data, int len)
{
  SPI_SELECT(spi, SPIDEV_DISPLAY(0), true);
  SPI_CMDDATA(spi, SPIDEV_DISPLAY(0), true);   /* DC low = command */
  SPI_SEND(spi, cmd);
  if (len > 0)
    {
      SPI_CMDDATA(spi, SPIDEV_DISPLAY(0), false); /* DC high = data */
      for (int i = 0; i < len; i++)
        {
          SPI_SEND(spi, data[i]);
        }
    }
  SPI_SELECT(spi, SPIDEV_DISPLAY(0), false);
}

static void st7796_init_and_fill(struct spi_dev_s *spi)
{
  static uint8_t line[LCD_W * 2];
  uint8_t caset[4] = {0x00, 0x00, (LCD_W - 1) >> 8, (LCD_W - 1) & 0xff};
  uint8_t raset[4] = {0x00, 0x00, (LCD_H - 1) >> 8, (LCD_H - 1) & 0xff};
  int i;

  SPI_LOCK(spi, true);
  SPI_SETMODE(spi, SPIDEV_MODE0);
  SPI_SETBITS(spi, 8);
  SPI_SETFREQUENCY(spi, 20000000);

  /* vendor init */

  for (i = 0; i < (int)(sizeof(g_st7796_init) / sizeof(g_st7796_init[0])); i++)
    {
      st7796_wrcmd(spi, g_st7796_init[i].cmd, g_st7796_init[i].data,
                   g_st7796_init[i].len);
      if (g_st7796_init[i].delayms)
        {
          up_mdelay(g_st7796_init[i].delayms);
        }
    }

  /* self-test: fill the whole panel GREEN so we can SEE the panel display */

  for (i = 0; i < LCD_W; i++)
    {
      line[2 * i]     = 0x07;   /* RGB565 green, MSB */
      line[2 * i + 1] = 0xE0;   /* LSB */
    }

  st7796_wrcmd(spi, 0x2A, caset, 4);   /* column addr 0..W-1 */
  st7796_wrcmd(spi, 0x2B, raset, 4);   /* row addr 0..H-1 */

  SPI_SELECT(spi, SPIDEV_DISPLAY(0), true);
  SPI_CMDDATA(spi, SPIDEV_DISPLAY(0), true);
  SPI_SEND(spi, 0x2C);                  /* RAMWR */
  SPI_CMDDATA(spi, SPIDEV_DISPLAY(0), false);
  for (i = 0; i < LCD_H; i++)
    {
      SPI_SNDBLOCK(spi, line, LCD_W * 2);
    }
  SPI_SELECT(spi, SPIDEV_DISPLAY(0), false);

  SPI_LOCK(spi, false);

  syslog(LOG_ERR, "[wslcd] ST7796 vendor init + green fill done\n");
  up_mdelay(1500);   /* hold the green fill ~1.5s before fb takes over */
}

int board_lcd_initialize(void)
{
  struct i2c_master_s *i2c;
  struct ioexpander_dev_s *ioe;
  int ret;

  syslog(LOG_ERR, "[wslcd] init start\n");
  esp32s3_configgpio(GPIO_LCD_BL, OUTPUT);
  esp32s3_gpiowrite(GPIO_LCD_BL, true);
  esp32s3_configgpio(GPIO_LCD_DC, OUTPUT);
  esp32s3_gpiowrite(GPIO_LCD_DC, true);

  i2c = esp32s3_i2cbus_initialize(LCD_I2C_PORTNO);
  if (i2c == NULL)
    {
      syslog(LOG_ERR, "[wslcd] I2C%d FAILED\n", LCD_I2C_PORTNO);
    }
  else
    {
      ioe = pca9557_initialize(i2c, &g_tca9554);
      if (ioe == NULL)
        {
          syslog(LOG_ERR, "[wslcd] TCA9554 FAILED\n");
        }
      else
        {
          ret  = IOEXP_SETDIRECTION(ioe, EXIO_PWR, IOEXPANDER_DIRECTION_OUT);
          ret |= IOEXP_SETDIRECTION(ioe, EXIO_LCD_RST, IOEXPANDER_DIRECTION_OUT);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_PWR, false);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_LCD_RST, false);
          nxsig_usleep(100000);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_LCD_RST, true);
          nxsig_usleep(120000);
          syslog(LOG_ERR, "[wslcd] TCA9554 ok ret=%d\n", ret);
        }
    }

  g_spidev = esp32s3_spibus_initialize(LCD_SPI_PORTNO);
  if (g_spidev == NULL)
    {
      syslog(LOG_ERR, "[wslcd] SPI%d FAILED\n", LCD_SPI_PORTNO);
      return -ENODEV;
    }

  syslog(LOG_ERR, "[wslcd] init done, SPI ok\n");
  return OK;
}

struct lcd_dev_s *board_lcd_getdev(int devno)
{
  g_lcd = st7789_lcdinitialize(g_spidev);
  syslog(LOG_ERR, "[wslcd] st7789_lcdinitialize -> %s\n", g_lcd ? "OK" : "NULL");

  /* Send the real ST7796 init + a green self-test fill */

  if (g_spidev != NULL)
    {
      st7796_init_and_fill(g_spidev);
    }

  return g_lcd;
}

void board_lcd_uninitialize(void)
{
  if (g_lcd != NULL)
    {
      g_lcd->setpower(g_lcd, 0);
    }
}
