text:
That's it — **the LCD is unpowered because we never turned on its AXP2101 rail.** I got the exact vendor power sequence: the AXP2101 (I²C @ 0x34) must enable **ALDO1=3.3V, BLDO1=1.5V, BLDO2=2.8V** *before* the display init. Our firmware skipped that entirely, so the ST7796 has no power — hence the all-`0xFF` reads and blank panel.

Let me add the AXP2101 power-on to the board init. This should finally bring the panel to life. Paste in the VM (`Ctrl-C` the server first):

```bash
export PATH=$HOME/bin:$HOME/openvela/prebuilts/gcc/linux-x86_64/xtensa-esp32s3-elf/bin:$HOME/.local/bin:$PATH
F=~/openvela/nuttx/boards/xtensa/esp32s3/esp32s3-devkit/src/esp32s3_st7789.c

python3 - "$F" <<'PY'
import sys
f=sys.argv[1]; s=open(f).read()

# 1) add AXP2101 helpers before board_lcd_initialize
helpers='''static int axp_wr(struct i2c_master_s *i2c, uint8_t reg, uint8_t val)
{
  struct i2c_msg_s msg;
  uint8_t buf[2];
  buf[0] = reg; buf[1] = val;
  msg.frequency = 400000; msg.addr = 0x34; msg.flags = 0;
  msg.buffer = buf; msg.length = 2;
  return I2C_TRANSFER(i2c, &msg, 1);
}

static uint8_t axp_rd(struct i2c_master_s *i2c, uint8_t reg)
{
  struct i2c_msg_s msg[2];
  uint8_t val = 0xff;
  msg[0].frequency = 400000; msg[0].addr = 0x34; msg[0].flags = 0;
  msg[0].buffer = &reg; msg[0].length = 1;
  msg[1].frequency = 400000; msg[1].addr = 0x34; msg[1].flags = I2C_M_READ;
  msg[1].buffer = &val; msg[1].length = 1;
  I2C_TRANSFER(i2c, msg, 2);
  return val;
}

static void axp2101_power_lcd(struct i2c_master_s *i2c)
{
  uint8_t id = axp_rd(i2c, 0x03);
  uint8_t en;
  syslog(LOG_ERR, "[wslcd] AXP2101 chipid(0x03)=0x%02x (expect 0x4a)\\n", id);
  axp_wr(i2c, 0x92, (3300 - 500) / 100);   /* ALDO1 = 3.3V */
  axp_wr(i2c, 0x96, (1500 - 500) / 100);   /* BLDO1 = 1.5V */
  axp_wr(i2c, 0x97, (2800 - 500) / 100);   /* BLDO2 = 2.8V */
  en = axp_rd(i2c, 0x90);
  axp_wr(i2c, 0x90, en | 0x31);            /* enable ALDO1|BLDO1|BLDO2 */
  syslog(LOG_ERR, "[wslcd] AXP2101 LDO en 0x90: 0x%02x -> 0x%02x\\n", en, en | 0x31);
  nxsig_usleep(50000);
}

'''
s = s.replace('int board_lcd_initialize(void)', helpers + 'int board_lcd_initialize(void)', 1)

# 2) call it right after the i2c bus is up (before the expander init)
anchor='  i2c = esp32s3_i2cbus_initialize(LCD_I2C_PORTNO);\n  if (i2c == NULL) { syslog(LOG_ERR, "[wslcd] I2C FAILED\\n"); }\n  else\n    {\n'
inject=anchor+'      axp2101_power_lcd(i2c);\n'
s = s.replace(anchor, inject, 1)
open(f,'w').write(s)
print("patched AXP2101")
PY

