  struct i2c_msg_s m[2]; uint8_t v=0xff;
  m[0].frequency=400000; m[0].addr=0x34; m[0].flags=0; m[0].buffer=&r; m[0].length=1;
  m[1].frequency=400000; m[1].addr=0x34; m[1].flags=I2C_M_READ; m[1].buffer=&v; m[1].length=1;
  I2C_TRANSFER(i2c, m, 2); return v;
}
static void axp_power(struct i2c_master_s *i2c)
{
  uint8_t en;
  syslog(LOG_ERR, "[wslcd] AXP2101 id=0x%02x\n", axp_rd(i2c, 0x03));
  axp_wr(i2c, 0x92, (3300-500)/100);
  axp_wr(i2c, 0x96, (1500-500)/100);
  axp_wr(i2c, 0x97, (2800-500)/100);
  en = axp_rd(i2c, 0x90);
  axp_wr(i2c, 0x90, en | 0x31);
  nxsig_usleep(50000);
}

static void wr(struct spi_dev_s *s, uint8_t c, const uint8_t *d, int n)
{
  SPI_SELECT(s, SPIDEV_DISPLAY(0), true);
  SPI_CMDDATA(s, SPIDEV_DISPLAY(0), true);
  SPI_SEND(s, c);
  if (n > 0)
    {
      SPI_CMDDATA(s, SPIDEV_DISPLAY(0), false);
      for (int i = 0; i < n; i++) SPI_SEND(s, d[i]);
    }
  SPI_SELECT(s, SPIDEV_DISPLAY(0), false);
}

static void draw_bars(struct spi_dev_s *s)
{
  static uint8_t line[LCD_W*2];
  static const uint16_t bars[8] =
    {0xF800,0x07E0,0x001F,0xFFE0,0x07FF,0xF81F,0xFFFF,0x0000};
  uint8_t ca[4]={0x00,0x00,(LCD_W-1)>>8,(LCD_W-1)&0xff};
  uint8_t ra[4]={0x00,0x00,(LCD_H-1)>>8,(LCD_H-1)&0xff};
  int i,y,k; uint16_t c;

  SPI_LOCK(s, true);
  SPI_SETMODE(s, SPIDEV_MODE0);
  SPI_SETBITS(s, 8);
  SPI_SETFREQUENCY(s, 20000000);
  for (i = 0; i < (int)(sizeof(g_init)/sizeof(g_init[0])); i++)
    {
      wr(s, g_init[i].cmd, g_init[i].data, g_init[i].len);
      if (g_init[i].ms) up_mdelay(g_init[i].ms);
    }
  wr(s, 0x2A, ca, 4);
  wr(s, 0x2B, ra, 4);
  SPI_SELECT(s, SPIDEV_DISPLAY(0), true);
  SPI_CMDDATA(s, SPIDEV_DISPLAY(0), true);
  SPI_SEND(s, 0x2C);
  SPI_CMDDATA(s, SPIDEV_DISPLAY(0), false);
  for (y = 0; y < LCD_H; y++)
    {
      c = bars[(y * 8) / LCD_H];
      for (k = 0; k < LCD_W; k++) { line[2*k] = c >> 8; line[2*k+1] = c & 0xff; }
      SPI_SNDBLOCK(s, line, LCD_W * 2);
    }
  SPI_SELECT(s, SPIDEV_DISPLAY(0), false);
  SPI_LOCK(s, false);
  syslog(LOG_ERR, "[wslcd] color bars drawn\n");
  up_mdelay(20000);
}

int board_lcd_initialize(void)
{
  struct i2c_master_s *i2c;
  struct ioexpander_dev_s *ioe;
  int ret;
  syslog(LOG_ERR, "[wslcd] init start\n");
  esp32s3_configgpio(GPIO_LCD_BL, OUTPUT); esp32s3_gpiowrite(GPIO_LCD_BL, true);
  esp32s3_configgpio(GPIO_LCD_DC, OUTPUT); esp32s3_gpiowrite(GPIO_LCD_DC, true);
  i2c = esp32s3_i2cbus_initialize(LCD_I2C_PORTNO);
  if (i2c == NULL) { syslog(LOG_ERR, "[wslcd] I2C FAILED\n"); }
  else
    {
      axp_power(i2c);
      ioe = pca9557_initialize(i2c, &g_tca);
      if (ioe == NULL) { syslog(LOG_ERR, "[wslcd] TCA9554 FAILED\n"); }
      else
        {
          ret  = IOEXP_SETDIRECTION(ioe, EXIO_PWR, IOEXPANDER_DIRECTION_OUT);
          ret |= IOEXP_SETDIRECTION(ioe, EXIO_LCD_RST, IOEXPANDER_DIRECTION_OUT);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_PWR, false);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_LCD_RST, false);
          nxsig_usleep(100000);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_LCD_RST, true);
          nxsig_usleep(120000);
          syslog(LOG_ERR, "[wslcd] TCA9554 ret=%d\n", ret);
        }
    }
  g_spidev = esp32s3_spibus_initialize(LCD_SPI_PORTNO);
  if (g_spidev == NULL) { syslog(LOG_ERR, "[wslcd] SPI FAILED\n"); return -ENODEV; }
  syslog(LOG_ERR, "[wslcd] SPI ok\n");
  return OK;
}

struct lcd_dev_s *board_lcd_getdev(int devno)
{
  g_lcd = st7789_lcdinitialize(g_spidev);
  syslog(LOG_ERR, "[wslcd] st7789 -> %s\n", g_lcd ? "OK" : "NULL");
  if (g_spidev != NULL) draw_bars(g_spidev);
  return g_lcd;
}

void board_lcd_uninitialize(void)
{
  if (g_lcd != NULL) g_lcd->setpower(g_lcd, 0);
}
EOF

