Now let me give you a **proper full-screen image** — 8 color bars, bit-banged across the whole panel (fixing the orientation/window so it fills completely, and holding DC high through the pixel stream so it draws faster). Paste in the VM (`Ctrl-C` server):

```bash
export PATH=$HOME/bin:$HOME/openvela/prebuilts/gcc/linux-x86_64/xtensa-esp32s3-elf/bin:$HOME/.local/bin:$PATH
cat > ~/openvela/nuttx/boards/xtensa/esp32s3/esp32s3-devkit/src/esp32s3_st7789.c <<'EOF'
/* Waveshare ESP32-S3-Touch-LCD-3.5: bit-banged ST7796 color-bar image. */
#include <nuttx/config.h>
#include <stdint.h>
#include <stdbool.h>
#include <syslog.h>
#include <nuttx/arch.h>
#include <nuttx/signal.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/lcd/lcd.h>
#include <nuttx/ioexpander/ioexpander.h>
#include <nuttx/ioexpander/pca9557.h>
#include "esp32s3_i2c.h"
#include "esp32s3_gpio.h"

#define PIN_MOSI 1
#define PIN_CLK  5
#define PIN_DC   3
#define PIN_BL   6
#define XRES     480
#define YRES     320

static struct pca9557_config_s g_tca = { 0x20, 100000, NULL };

static int axp_wr(struct i2c_master_s *i2c, uint8_t r, uint8_t v)
{
  struct i2c_msg_s m; uint8_t b[2]; b[0]=r; b[1]=v;
  m.frequency=400000; m.addr=0x34; m.flags=0; m.buffer=b; m.length=2;
  return I2C_TRANSFER(i2c, &m, 1);
}
static void axp_power(struct i2c_master_s *i2c)
{
  axp_wr(i2c,0x80,0x01); axp_wr(i2c,0x82,(3300-1500)/100);
  axp_wr(i2c,0x90,0x00); axp_wr(i2c,0x91,0x00); nxsig_usleep(5000);
  axp_wr(i2c,0x92,(3300-500)/100); axp_wr(i2c,0x96,(1500-500)/100);
  axp_wr(i2c,0x97,(2800-500)/100); axp_wr(i2c,0x90,0x31); nxsig_usleep(120000);
}

static void bb_byte(uint8_t b)
{
  int i;
  for (i = 0; i < 8; i++)
    {
      esp32s3_gpiowrite(PIN_MOSI, (b & 0x80) != 0); b <<= 1;
      esp32s3_gpiowrite(PIN_CLK, true);
      esp32s3_gpiowrite(PIN_CLK, false);
    }
}
static void bb_cmd(uint8_t c){ esp32s3_gpiowrite(PIN_DC, false); bb_byte(c); }
static void bb_dat(uint8_t d){ esp32s3_gpiowrite(PIN_DC, true);  bb_byte(d); }

static void bb_go(void)
{
  static const uint16_t bars[8] =
    {0xF800,0x07E0,0x001F,0xFFE0,0x07FF,0xF81F,0xFFFF,0x0000};
  int x, y; uint16_t c; uint8_t hi, lo;

  esp32s3_configgpio(PIN_MOSI, OUTPUT);
  esp32s3_configgpio(PIN_CLK, OUTPUT);
  esp32s3_configgpio(PIN_DC, OUTPUT);
  esp32s3_gpiowrite(PIN_CLK, false);

  bb_cmd(0x01); up_mdelay(150);
  bb_cmd(0x11); up_mdelay(120);
  bb_cmd(0xF0); bb_dat(0xC3); bb_cmd(0xF0); bb_dat(0x96);
  bb_cmd(0x36); bb_dat(0x28);            /* MADCTL: landscape (MV) + BGR */
  bb_cmd(0x3A); bb_dat(0x55);
  bb_cmd(0xF0); bb_dat(0x3C); bb_cmd(0xF0); bb_dat(0x69);
  bb_cmd(0x21);
  bb_cmd(0x29); up_mdelay(120);
  bb_cmd(0x2A); bb_dat(0); bb_dat(0); bb_dat((XRES-1)>>8); bb_dat((XRES-1)&0xff);
  bb_cmd(0x2B); bb_dat(0); bb_dat(0); bb_dat((YRES-1)>>8); bb_dat((YRES-1)&0xff);
  bb_cmd(0x2C);
  esp32s3_gpiowrite(PIN_DC, true);       /* pixel data phase: DC stays high */
  for (y = 0; y < YRES; y++)
    {
      c = bars[(y * 8) / YRES]; hi = c >> 8; lo = c & 0xff;
      for (x = 0; x < XRES; x++) { bb_byte(hi); bb_byte(lo); }
    }
  syslog(LOG_ERR, "[wslcd] BITBANG color bars done\n");
}

int board_lcd_initialize(void)
{
  struct i2c_master_s *i2c;
  struct ioexpander_dev_s *ioe;
  syslog(LOG_ERR, "[wslcd] BITBANG start\n");
  esp32s3_configgpio(PIN_BL, OUTPUT); esp32s3_gpiowrite(PIN_BL, true);
  i2c = esp32s3_i2cbus_initialize(0);
  if (i2c != NULL)
    {
      axp_power(i2c);
      ioe = pca9557_initialize(i2c, &g_tca);
      if (ioe != NULL)
        {
          IOEXP_SETDIRECTION(ioe, 0, IOEXPANDER_DIRECTION_OUT);
          IOEXP_SETDIRECTION(ioe, 1, IOEXPANDER_DIRECTION_OUT);
          IOEXP_WRITEPIN(ioe, 0, false);
          IOEXP_WRITEPIN(ioe, 1, false); nxsig_usleep(100000);
          IOEXP_WRITEPIN(ioe, 1, true);  nxsig_usleep(120000);
        }
    }
  bb_go();
  return OK;
}

struct lcd_dev_s *board_lcd_getdev(int devno){ return NULL; }
void board_lcd_uninitialize(void){}
EOF

