  esp32s3_gpiowrite(PIN_DC,true);  {uint8_t w[4]={0,0,0,239}; SPI_SNDBLOCK(spi,w,4);}
  esp32s3_gpiowrite(PIN_DC,false); SPI_SEND(spi,0x2B);
  esp32s3_gpiowrite(PIN_DC,true);  {uint8_t w[4]={0,0,0,159}; SPI_SNDBLOCK(spi,w,4);}
  esp32s3_gpiowrite(PIN_DC,false); SPI_SEND(spi,0x2C);
  esp32s3_gpiowrite(PIN_DC,true);
  for (i=0;i<160;i++) SPI_SNDBLOCK(spi,row,240*2);
  SPI_SELECT(spi,SPIDEV_DISPLAY(0),false);
  SPI_LOCK(spi,false);
  syslog(LOG_ERR,"[wslcd] SPI red-rect sent\n");
}

