Now the fast version — register-level bit-bang (`W1TS`/`W1TC` direct writes, ~4 instructions/bit instead of a function call), drawing the full color-bar image and timing it so we see the real speed. Paste in the VM (`Ctrl-C` server):

```bash
export PATH=$HOME/bin:$HOME/openvela/prebuilts/gcc/linux-x86_64/xtensa-esp32s3-elf/bin:$HOME/.local/bin:$PATH
cat > ~/openvela/nuttx/boards/xtensa/esp32s3/esp32s3-devkit/src/esp32s3_st7789.c <<'EOF'
/* Waveshare ESP32-S3-Touch-LCD-3.5: FAST register-level bit-bang ST7796. */
#include <nuttx/config.h>
#include <stdint.h>
#include <stdbool.h>
#include <syslog.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/signal.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/lcd/lcd.h>
#include <nuttx/ioexpander/ioexpander.h>
#include <nuttx/ioexpander/pca9557.h>
#include "esp32s3_i2c.h"
#include "esp32s3_gpio.h"
#include "hardware/esp32s3_gpio.h"

#define PIN_MOSI 1
#define PIN_CLK  5
#define PIN_DC   3
#define PIN_BL   6
#define XRES     480
#define YRES     320
#define MOSI_M   (1U << PIN_MOSI)
#define CLK_M    (1U << PIN_CLK)

static struct pca9557_config_s g_tca = { 0x20, 100000, NULL };

static int axp_wr(struct i2c_master_s *i2c, uint8_t r, uint8_t v)
{
  struct i2c_msg_s m; uint8_t b[2]; b[0]=r; b[1]=v;
  m.frequency=400000; m.addr=0x34; m.flags=0; m.buffer=b; m.length=2;
  return I2C_TRANSFER(i2c, &m, 1);
}
static void axp_power(struct i2c_master_s *i2c)
{
  axp_wr(i2c,0x80,0x01); axp_wr(i2c,0x82,(3300-1500)/100);
  axp_wr(i2c,0x90,0x00); axp_wr(i2c,0x91,0x00); nxsig_usleep(5000);
  axp_wr(i2c,0x92,(3300-500)/100); axp_wr(i2c,0x96,(1500-500)/100);
  axp_wr(i2c,0x97,(2800-500)/100); axp_wr(i2c,0x90,0x31); nxsig_usleep(120000);
}

static inline void fbyte(uint8_t b)
{
  int i;
  for (i = 0; i < 8; i++)
    {
      if (b & 0x80) putreg32(MOSI_M, GPIO_OUT_W1TS_REG);
      else          putreg32(MOSI_M, GPIO_OUT_W1TC_REG);
      b <<= 1;
      putreg32(CLK_M, GPIO_OUT_W1TS_REG);
      putreg32(CLK_M, GPIO_OUT_W1TC_REG);
    }
}
static void fc(uint8_t c){ esp32s3_gpiowrite(PIN_DC,false); fbyte(c); }
static void fd(uint8_t d){ esp32s3_gpiowrite(PIN_DC,true);  fbyte(d); }

static void panel(void)
{
  static const uint16_t bars[8] =
    {0xF800,0x07E0,0x001F,0xFFE0,0x07FF,0xF81F,0xFFFF,0x0000};
  clock_t t0, t1; int x, y; uint16_t c; uint8_t hi, lo;

  esp32s3_configgpio(PIN_MOSI,OUTPUT); esp32s3_configgpio(PIN_CLK,OUTPUT); esp32s3_configgpio(PIN_DC,OUTPUT);
  putreg32(CLK_M, GPIO_OUT_W1TC_REG);
  fc(0x01); up_mdelay(150); fc(0x11); up_mdelay(120);
  fc(0xF0); fd(0xC3); fc(0xF0); fd(0x96);
  fc(0x36); fd(0x28); fc(0x3A); fd(0x55);
  fc(0xF0); fd(0x3C); fc(0xF0); fd(0x69);
  fc(0x21); fc(0x29); up_mdelay(120);
  fc(0x2A); fd(0); fd(0); fd((XRES-1)>>8); fd((XRES-1)&0xff);
  fc(0x2B); fd(0); fd(0); fd((YRES-1)>>8); fd((YRES-1)&0xff);
  fc(0x2C); esp32s3_gpiowrite(PIN_DC,true);
  t0 = clock_systime_ticks();
  for (y = 0; y < YRES; y++)
    {
      c = bars[(y * 8) / YRES]; hi = c >> 8; lo = c & 0xff;
      for (x = 0; x < XRES; x++) { fbyte(hi); fbyte(lo); }
    }
  t1 = clock_systime_ticks();
  syslog(LOG_ERR, "[wslcd] FAST bars: full 480x320 frame in %lu ms\n",
         (unsigned long)TICK2MSEC(t1 - t0));
}

int board_lcd_initialize(void)
{
  struct i2c_master_s *i2c; struct ioexpander_dev_s *ioe;
  syslog(LOG_ERR,"[wslcd] FAST start\n");
  esp32s3_configgpio(PIN_BL,OUTPUT); esp32s3_gpiowrite(PIN_BL,true);
  i2c = esp32s3_i2cbus_initialize(0);
  if (i2c){ axp_power(i2c);
    ioe = pca9557_initialize(i2c,&g_tca);
    if (ioe){ IOEXP_SETDIRECTION(ioe,0,IOEXPANDER_DIRECTION_OUT); IOEXP_SETDIRECTION(ioe,1,IOEXPANDER_DIRECTION_OUT);
      IOEXP_WRITEPIN(ioe,0,false); IOEXP_WRITEPIN(ioe,1,false); nxsig_usleep(100000);
      IOEXP_WRITEPIN(ioe,1,true); nxsig_usleep(120000); } }
  panel();
  return OK;
}
struct lcd_dev_s *board_lcd_getdev(int devno){ return NULL; }
void board_lcd_uninitialize(void){}
EOF

