static void bbb(uint8_t b){int i;for(i=0;i<8;i++){esp32s3_gpiowrite(PIN_MOSI,(b&0x80)!=0);b<<=1;esp32s3_gpiowrite(PIN_CLK,true);esp32s3_gpiowrite(PIN_CLK,false);}}
static void bc(uint8_t c){esp32s3_gpiowrite(PIN_DC,false);bbb(c);}
static void bd(uint8_t d){esp32s3_gpiowrite(PIN_DC,true);bbb(d);}
static void bb_black(void)
{
  long n;
  esp32s3_configgpio(PIN_MOSI,OUTPUT);esp32s3_configgpio(PIN_CLK,OUTPUT);esp32s3_configgpio(PIN_DC,OUTPUT);
  esp32s3_gpiowrite(PIN_CLK,false);
  bc(0x01);up_mdelay(150);bc(0x11);up_mdelay(120);
  bc(0xF0);bd(0xC3);bc(0xF0);bd(0x96);bc(0x36);bd(0x28);bc(0x3A);bd(0x55);
  bc(0xF0);bd(0x3C);bc(0xF0);bd(0x69);bc(0x21);bc(0x29);up_mdelay(120);
  bc(0x2A);bd(0);bd(0);bd((XRES-1)>>8);bd((XRES-1)&0xff);
  bc(0x2B);bd(0);bd(0);bd((YRES-1)>>8);bd((YRES-1)&0xff);
  bc(0x2C);esp32s3_gpiowrite(PIN_DC,true);
  for(n=0;n<(long)XRES*YRES;n++){bbb(0x00);bbb(0x00);}
