}

static void spi_test(void)
{
  struct spi_dev_s *spi=esp32s3_spibus_initialize(2);
  static uint8_t row[240*2]; int i;
  if(!spi){syslog(LOG_ERR,"[wslcd] SPI NULL\n");return;}
  esp32s3_configgpio(PIN_MOSI,OUTPUT); esp32s3_gpio_matrix_out(PIN_MOSI,FSPID_OUT_IDX,0,0);
  esp32s3_configgpio(PIN_CLK,OUTPUT);  esp32s3_gpio_matrix_out(PIN_CLK,FSPICLK_OUT_IDX,0,0);
