  for(i=0;i<240;i++){row[2*i]=0xF8;row[2*i+1]=0x00;}
  SPI_LOCK(spi,true);SPI_SETMODE(spi,SPIDEV_MODE0);SPI_SETBITS(spi,8);SPI_SETFREQUENCY(spi,10000000);
  SPI_SELECT(spi,SPIDEV_DISPLAY(0),true);
  esp32s3_gpiowrite(PIN_DC,false);SPI_SEND(spi,0x2A);
  esp32s3_gpiowrite(PIN_DC,true);{uint8_t w[4]={0,0,0,239};SPI_SNDBLOCK(spi,w,4);}
  esp32s3_gpiowrite(PIN_DC,false);SPI_SEND(spi,0x2B);
  esp32s3_gpiowrite(PIN_DC,true);{uint8_t w[4]={0,0,0,159};SPI_SNDBLOCK(spi,w,4);}
  esp32s3_gpiowrite(PIN_DC,false);SPI_SEND(spi,0x2C);
  esp32s3_gpiowrite(PIN_DC,true);
  for(i=0;i<160;i++)SPI_SNDBLOCK(spi,row,240*2);
  SPI_SELECT(spi,SPIDEV_DISPLAY(0),false);SPI_LOCK(spi,false);
  syslog(LOG_ERR,"[wslcd] SPI(CS=4) red-rect sent\n");
}

int board_lcd_initialize(void)
{
  struct i2c_master_s *i2c; struct ioexpander_dev_s *ioe;
  syslog(LOG_ERR,"[wslcd] CS-TEST start\n");
  esp32s3_configgpio(PIN_BL,OUTPUT);esp32s3_gpiowrite(PIN_BL,true);
  i2c=esp32s3_i2cbus_initialize(0);
  if(i2c){axp_power(i2c);ioe=pca9557_initialize(i2c,&g_tca);
    if(ioe){IOEXP_SETDIRECTION(ioe,0,IOEXPANDER_DIRECTION_OUT);IOEXP_SETDIRECTION(ioe,1,IOEXPANDER_DIRECTION_OUT);
      IOEXP_WRITEPIN(ioe,0,false);IOEXP_WRITEPIN(ioe,1,false);nxsig_usleep(100000);
      IOEXP_WRITEPIN(ioe,1,true);nxsig_usleep(120000);}}
  bb_black();
  spi_test();
