f=sys.argv[1]; s=open(f).read()
test='''  panel_init();
  /* SELF-TEST: red full, green rect, blue rect (nested) via bb_window */
  {
    uint32_t base; long n;
    bb_window(0,XRES-1,0,YRES-1);
    base=(*(volatile uint32_t*)REG_OUT)&~(MOSI_M|CLK_M);
    for(n=0;n<(long)XRES*YRES;n++){ffbyte(0xF8,base);ffbyte(0x00,base);}
    bb_window(100,300,80,240);
    base=(*(volatile uint32_t*)REG_OUT)&~(MOSI_M|CLK_M);
    for(n=0;n<201L*161;n++){ffbyte(0x07,base);ffbyte(0xE0,base);}
    bb_window(200,260,140,180);
    base=(*(volatile uint32_t*)REG_OUT)&~(MOSI_M|CLK_M);
    for(n=0;n<61L*41;n++){ffbyte(0x00,base);ffbyte(0x1F,base);}
    syslog(LOG_ERR,"[wslcd] selftest done\\n");
    up_mdelay(8000);
  }'''
assert '  panel_init();' in s
s=s.replace('  panel_init();', test, 1)
open(f,'w').write(s); print("selftest inserted:", 'selftest done' in s)
