621	/* red bell when any pet shows a sudden appetite drop */
622	static void update_bell(void)
623	{
624	  int alert = 0;
625	  int n = velapaw_identity_count();
626	  for (int i = 0; i < n; i++)
627	    {
628	      const struct velapaw_pet *p = velapaw_identity_get(i);
629	      if (p && pet_alert_drop(i, p))
630	        {
631	          alert = 1;
632	          break;
633	        }
634	    }
635	  if (g_bell)
636	    {
637	      lv_obj_set_style_text_color(g_bell,
638	                                  lv_color_hex(alert ? COL_UNK : COL_DIM), 0);
639	    }
640	}
