642	static void refresh_pets(void)
643	{
644	  if (g_pets_box == NULL)
645	    {
646	      return;
647	    }
648	  lv_obj_clean(g_pets_box);
649	  int n = velapaw_identity_count();
650	  if (n == 0)
651	    {
652	      lv_obj_t *l = make_label(g_pets_box, &lv_font_montserrat_16, COL_DIM);
653	      lv_label_set_text(l, "No pets yet - enroll one");
654	      update_bell();
655	      return;
656	    }
657	  for (int i = 0; i < n; i++)
658	    {
659	      const struct velapaw_pet *p = velapaw_identity_get(i);
660	      int today = velapaw_store_today_total(i);
661	      int meals = velapaw_store_today_meals(i);
662	      int avg   = velapaw_store_baseline_g(i);
663	      int week  = velapaw_store_week_total(i);
664	      int pct   = pet_appetite_pct(i, p);
665	      int alert = pet_alert_drop(i, p);
666	
667	      lv_obj_t *row = make_card(g_pets_box, COL_W - 40, 196, COL_CARD2);
668	      lv_obj_set_flex_flow(row, LV_FLEX_FLOW_COLUMN);
669	      lv_obj_set_style_pad_row(row, 2, 0);
670	
671	      lv_obj_t *nm = make_label(row, &lv_font_montserrat_22, COL_TEXT);
672	      lv_label_set_text(nm, p->name);
673	
674	      lv_obj_t *l1 = make_label(row, &lv_font_montserrat_14,
675	                                (today >= p->daily_limit_g) ? COL_FED : COL_DIM);
676	      lv_label_set_text_fmt(l1, "Today: %d / %d g   -   %d meals",
677	                            today, p->daily_limit_g, meals);
678	      if (today >= p->daily_limit_g)
679	        {
680	          lv_obj_t *lim = make_label(row, &lv_font_montserrat_14, COL_FED);
681	          lv_label_set_text(lim, LV_SYMBOL_OK " Daily limit reached");
682	        }
683	
684	      lv_obj_t *l2 = make_label(row, &lv_font_montserrat_14, COL_DIM);
685	      lv_label_set_text_fmt(l2, "Avg: %d g/day    Week: %d g", avg, week);
686	
687	      uint32_t pcol = (pct >= 70) ? COL_FED : (pct >= 40) ? COL_COOL : COL_UNK;
688	      lv_obj_t *l3 = make_label(row, &lv_font_montserrat_16, pcol);
689	      if (alert)
690	        {
691	          lv_label_set_text_fmt(l3, LV_SYMBOL_WARNING
692	                                " Appetite drop (%d%%)", pct);
693	        }
694	      else
695	        {
696	          lv_label_set_text_fmt(l3, "Appetite: %d%%", pct);
697	        }
698	
699	      /* Body Condition Score from the 2nd on-device model */
700	      int bcs = velapaw_store_get_bcs(i);
701	      const char *bnm = (bcs == 0) ? "Under" : (bcs == 1) ? "Ideal"
702	                        : (bcs == 2) ? "Over" : "-";
703	      uint32_t bcol = (bcs == 1) ? COL_FED : (bcs < 0) ? COL_DIM : COL_COOL;
704	      lv_obj_t *l4 = make_label(row, &lv_font_montserrat_16, bcol);
705	      if (bcs == 0 || bcs == 2)   /* under/over: nudge to a vet */
706	        {
707	          lv_label_set_text_fmt(l4, "BCS: %s  " LV_SYMBOL_RIGHT
708	                                "  consider a vet check", bnm);
709	        }
710	      else
711	        {
712	          lv_label_set_text_fmt(l4, "BCS: %s", bnm);
713	        }
714	
715	      /* 7-day intake sparkline (oldest -> today) */
716	      lv_obj_t *spark = lv_obj_create(row);
717	      lv_obj_set_size(spark, COL_W - 80, 40);
718	      lv_obj_set_style_bg_opa(spark, LV_OPA_TRANSP, 0);
719	      lv_obj_set_style_border_width(spark, 0, 0);
720	      lv_obj_set_style_pad_all(spark, 0, 0);
721	      lv_obj_clear_flag(spark, LV_OBJ_FLAG_SCROLLABLE);
722	      lv_obj_set_flex_flow(spark, LV_FLEX_FLOW_ROW);
723	      lv_obj_set_flex_align(spark, LV_FLEX_ALIGN_SPACE_EVENLY,
724	                            LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
725	      int maxg = 1;
726	      for (int d = 0; d < VELAPAW_WEEK_DAYS; d++)
727	        {
728	          int g = velapaw_store_day_total(i, d);
729	          if (g > maxg)
730	            {
731	              maxg = g;
732	            }
733	        }
734	      for (int d = VELAPAW_WEEK_DAYS - 1; d >= 0; d--)
735	        {
