790	static void chart_press_cb(lv_event_t *e)
791	{
792	  (void)e;
793	  int32_t id = lv_chart_get_pressed_point(g_trend_chart);
794	  if (id == LV_CHART_POINT_NONE)
795	    {
796	      return;
797	    }
798	  int n = g_trend_month ? VELAPAW_HIST_DAYS : VELAPAW_WEEK_DAYS;
799	  int day_back = (n - 1) - (int)id;
800	  if (day_back == 0)
801	    {
802	      lv_label_set_text_fmt(g_trend_val, "today: %d g", (int)g_trend_vals[id]);
803	    }
804	  else if (day_back == 1)
805	    {
806	      lv_label_set_text_fmt(g_trend_val, "yesterday: %d g",
807	                            (int)g_trend_vals[id]);
808	    }
809	  else
810	    {
811	      lv_label_set_text_fmt(g_trend_val, "%d days ago: %d g", day_back,
812	                            (int)g_trend_vals[id]);
813	    }
814	}
