975	  lv_obj_clear_flag(hdr, LV_OBJ_FLAG_SCROLLABLE);
976	  g_crumb = make_label(hdr, &lv_font_montserrat_22, COL_TEXT);
977	  lv_label_set_text(g_crumb, "VelaPaw  -  Enroll");
978	  lv_obj_align(g_crumb, LV_ALIGN_LEFT_MID, 6, 0);
979	  g_bell = make_label(hdr, &lv_font_montserrat_22, COL_DIM);
980	  lv_label_set_text(g_bell, LV_SYMBOL_BELL);
981	  lv_obj_align(g_bell, LV_ALIGN_RIGHT_MID, -56, 0);
982	  lv_obj_add_flag(g_bell, LV_OBJ_FLAG_CLICKABLE);
983	  lv_obj_set_ext_click_area(g_bell, 24);   /* larger tap target */
984	  lv_obj_add_event_cb(g_bell, bell_cb, LV_EVENT_CLICKED, NULL);
985	#ifdef CONFIG_VELAPAW_INFER_TFLM
986	  static lv_image_dsc_t avatar;
987	  avatar.header.magic = LV_IMAGE_HEADER_MAGIC;
988	  avatar.header.cf = LV_COLOR_FORMAT_RGB565;       /* note: src is RGB888 */
989	#endif
990	  lv_obj_t *av = lv_obj_create(hdr);
991	  lv_obj_set_size(av, 44, 44);
992	  lv_obj_align(av, LV_ALIGN_RIGHT_MID, 0, 0);
993	  lv_obj_set_style_radius(av, 22, 0);
994	  lv_obj_set_style_bg_color(av, lv_color_hex(COL_BTN), 0);
995	  lv_obj_set_style_border_width(av, 0, 0);
996	  lv_obj_clear_flag(av, LV_OBJ_FLAG_SCROLLABLE);
997	
998	  /* tabview */
999	  g_tv = lv_tabview_create(col);
1000	  lv_tabview_set_tab_bar_position(g_tv, LV_DIR_TOP);
1001	  lv_tabview_set_tab_bar_size(g_tv, 48);
1002	  lv_obj_set_size(g_tv, COL_W, 720);
1003	  lv_obj_align(g_tv, LV_ALIGN_TOP_MID, 0, 72);
1004	  lv_obj_set_style_bg_color(g_tv, lv_color_hex(COL_BG), 0);
1005	  lv_obj_set_style_bg_color(lv_tabview_get_content(g_tv), lv_color_hex(COL_BG), 0);
1006	
1007	  lv_obj_t *t_en = lv_tabview_add_tab(g_tv, "Enroll");
1008	  lv_obj_t *t_rc = lv_tabview_add_tab(g_tv, "Recognize");
1009	  lv_obj_t *t_mp = lv_tabview_add_tab(g_tv, "My Pets");
1010	  lv_obj_t *t_tr = lv_tabview_add_tab(g_tv, "Trends");
1011	  lv_obj_set_style_bg_color(t_en, lv_color_hex(COL_BG), 0);
1012	  lv_obj_set_style_bg_color(t_rc, lv_color_hex(COL_BG), 0);
1013	  lv_obj_set_style_bg_color(t_mp, lv_color_hex(COL_BG), 0);
1014	  lv_obj_set_style_bg_color(t_tr, lv_color_hex(COL_BG), 0);
1015	
1016	  /* ---- init pipeline (before building tabs that read state) ---- */
1017	  g_be = velapaw_infer_active();
1018	  velapaw_camera_open();
1019	  g_be->init();
1020	  velapaw_identity_init();
1021	  velapaw_store_init();
1022	  velapaw_feeder_init();
1023	  for (int i = 0; i < VELAPAW_MAX_PETS; i++)
1024	    {
1025	      g_last_fed[i] = -100000;
1026	    }
1027	  g_view = 0;
1028	  velapaw_camera_mock_set_scene(g_view);
1029	
1030	  build_enroll(t_en);
1031	  build_recognize(t_rc);
1032	  build_pets(t_mp);
1033	  build_trends(t_tr);
1034	
1035	  /* keyboard floats above everything */
1036	  g_kb = lv_keyboard_create(lv_layer_top());
1037	  lv_keyboard_set_textarea(g_kb, g_name_ta);
1038	  lv_obj_add_flag(g_kb, LV_OBJ_FLAG_HIDDEN);
1039	  lv_obj_add_event_cb(g_kb, kb_cb, LV_EVENT_ALL, NULL);
1040	
1041	  refresh_enroll();
1042	  lv_label_set_text_fmt(g_count, "enrolled pets: %d", velapaw_identity_count());
1043	  lv_label_set_text_fmt(g_metrics, "backend %s   arena %lu KB", g_be->name,
1044	                        (unsigned long)g_be->arena_bytes() / 1024);
1045	
1046	  long last_frame = 0;
1047	  long last_recog = 0;
1048	  uint32_t last_tab = 99;
1049	  struct velapaw_frame frame;
1050	  velapaw_camera_get_frame(&frame);
1051	  show_frame(&frame);
1052	
1053	  while (1)
1054	    {
1055	      lv_timer_handler();
1056	
1057	      uint32_t tab = lv_tabview_get_tab_active(g_tv);
1058	      if (tab != last_tab)
1059	        {
1060	          last_tab = tab;
1061	          const char *nm = (tab == 0) ? "Enroll" :
1062	                           (tab == 1) ? "Recognize" :
1063	                           (tab == 2) ? "My Pets" : "Trends";
1064	          lv_label_set_text_fmt(g_crumb, "VelaPaw  -  %s", nm);
1065	          if (tab == 2)
1066	            {
1067	              refresh_pets();
1068	            }
1069	          else if (tab == 3)
1070	            {
1071	              refresh_trends();
1072	            }
1073	        }
1074	
1075	      ui_event_t ev = g_evt;
1076	      g_evt = EV_NONE;
1077	      if (ev == EV_VIEW)
1078	        {
1079	          g_view = (g_view + 1) % NUM_VIEWS;
1080	          velapaw_camera_mock_set_scene(g_view);
1081	          refresh_enroll();
1082	        }
1083	      else if (ev == EV_CAPTURE)
1084	        {
1085	          do_capture();
1086	        }
1087	      else if (ev == EV_SAVE)
1088	        {
1089	          do_save();
1090	        }
1091	      else if (ev == EV_NEXTDAY)
1092	        {
1093	          velapaw_store_roll_day();
1094	          refresh_pets();
1095	          refresh_trends();
1096	        }
1097	      else if (ev == EV_TREND_PREV || ev == EV_TREND_NEXT)
1098	        {
1099	          int cnt = velapaw_identity_count();
1100	          if (cnt > 0)
1101	            {
1102	              g_trend_pet = (ev == EV_TREND_NEXT)
1103	                            ? (g_trend_pet + 1) % cnt
1104	                            : (g_trend_pet + cnt - 1) % cnt;
1105	            }
1106	          refresh_trends();
1107	        }
1108	      else if (ev == EV_TREND_WEEK)
1109	        {
1110	          g_trend_month = 0;
1111	          refresh_trends();
1112	        }
1113	      else if (ev == EV_TREND_MONTH)
1114	        {
1115	          g_trend_month = 1;
1116	          refresh_trends();
1117	        }
1118	
1119	      long now = mono_ms();
1120	
1121	      if (now - last_frame > FRAME_INTERVAL_MS)
1122	        {
1123	          velapaw_camera_get_frame(&frame);
1124	          show_frame(&frame);
1125	          last_frame = now;
1126	        }
1127	
1128	      /* recognition only on the Recognize tab */
1129	      if (tab == 1 && now - last_recog > RECOG_INTERVAL_MS)
1130	        {
1131	          last_recog = now;
1132	          if (velapaw_identity_count() == 0)
1133	            {
1134	              lv_obj_set_style_text_color(g_status, lv_color_hex(COL_DIM), 0);
1135	              lv_label_set_text(g_status, "Enroll a pet first");
1136	            }
1137	          else
1138	            {
1139	              float emb[VELAPAW_EMBED_DIM];
1140	              g_be->embed(&frame, emb, VELAPAW_EMBED_DIM);
1141	              struct velapaw_match m;
1142	              velapaw_identity_match(emb, &m);
1143	              lv_label_set_text_fmt(g_metrics, "infer %lu ms   arena %lu KB",
1144	                                    (unsigned long)g_be->last_latency_us() / 1000,
1145	                                    (unsigned long)g_be->arena_bytes() / 1024);
1146	
1147	              if (m.id == VELAPAW_PET_UNKNOWN)
1148	                {
1149	                  g_cand = VELAPAW_PET_UNKNOWN;
1150	                  g_stable = 0;
1151	                  if (++g_absent >= 4)   /* ~5s gone (not a flicker) -> pet left */
1152	                    {
1153	                      g_fed_visit = VELAPAW_PET_UNKNOWN;
1154	                      g_bcs_for = VELAPAW_PET_UNKNOWN;
1155	                    }
1156	                  lv_obj_set_style_text_color(g_status, lv_color_hex(COL_UNK), 0);
1157	                  lv_label_set_text_fmt(g_status, "Unknown (%.2f)", m.score);
1158	                  lv_label_set_text(g_sub, "");
1159	                }
1160	              else
1161	                {
1162	                  const struct velapaw_pet *pet = velapaw_identity_get(m.id);
1163	                  g_absent = 0;
1164	
1165	                  /* Debounce identity flicker: multi-pet matching bounces frame
1166	                   * to frame, so only act once the same id holds for N frames. */
1167	                  if (m.id == g_cand)
1168	                    {
1169	                      g_stable++;
1170	                    }
1171	                  else
1172	                    {
1173	                      g_cand = m.id;
1174	                      g_stable = 1;
1175	                    }
1176	
1177	                  if (g_stable < RECOG_STABLE_N)
1178	                    {
1179	                      lv_obj_set_style_text_color(g_status, lv_color_hex(COL_DIM), 0);
1180	                      lv_label_set_text_fmt(g_status, "identifying %s ...",
1181	                                            pet->name);
1182	                      lv_label_set_text(g_sub, "");
1183	                    }
1184	                  else
1185	                    {
1186	                      lv_obj_set_style_text_color(g_status, lv_color_hex(COL_TEXT), 0);
1187	                      lv_label_set_text_fmt(g_status, "%s  (%.2f)", pet->name,
1188	                                            m.score);
1189	#ifdef VELAPAW_HAVE_BCS
1190	                      /* Majority-vote BCS over the first BCS_VOTES frames of the
1191	                       * visit so one bad frame can't set a wrong score. */
1192	                      if (m.id != g_bcs_for)   /* new pet -> start a fresh vote */
1193	                        {
1194	                          g_bcs_for = m.id;
1195	                          g_bcs_votes[0] = g_bcs_votes[1] = g_bcs_votes[2] = 0;
1196	                          g_bcs_nvotes = 0;
1197	                        }
1198	                      if (g_bcs_nvotes < BCS_VOTES)
1199	                        {
1200	                          int bcls = -1;
1201	                          float bconf = 0.0f;
1202	                          if (velapaw_infer_bcs(&frame, &bcls, &bconf) == 0 &&
1203	                              bcls >= 0 && bcls < 3)
1204	                            {
1205	                              g_bcs_votes[bcls]++;
1206	                              g_bcs_nvotes++;
1207	                              int best = 0;
1208	                              if (g_bcs_votes[1] > g_bcs_votes[best]) best = 1;
1209	                              if (g_bcs_votes[2] > g_bcs_votes[best]) best = 2;
1210	                              velapaw_store_set_bcs(m.id, best);  /* running majority */
1211	                            }
1212	                        }
1213	#endif
1214	                      long since = mono_ms() / 1000 - g_last_fed[m.id];
1215	                      if (m.id != g_fed_visit && since >= pet->cooldown_s)
1216	                        {
1217	                          if (velapaw_store_today_total(m.id) >=
1218	                              pet->daily_limit_g)
1219	                            {
1220	                              /* daily food budget spent - don't dispense */
