1226	                                  velapaw_store_today_total(m.id),
1227	                                  pet->daily_limit_g);
1228	                            }
1229	                          else
1230	                            {
1231	                              /* trim the last serving so today never exceeds
1232	                               * the daily limit (hard cap). */
1233	                              int remaining = pet->daily_limit_g -
1234	                                  velapaw_store_today_total(m.id);
1235	                              int amount = (pet->portion_g < remaining)
1236	                                           ? pet->portion_g : remaining;
1237	                              velapaw_feeder_dispense(amount);
1238	                              struct velapaw_feed_event ev2 =
1239	                                { m.id, (time_t)(mono_ms() / 1000),
1240	                                  amount, m.score, g_be->name };
1241	                              velapaw_store_log_feeding(&ev2);
1242	                              g_last_fed[m.id] = mono_ms() / 1000;
1243	                              g_fed_visit = m.id;
1244	                              lv_obj_set_style_text_color(g_sub,
1245	                                  lv_color_hex(COL_FED), 0);
1246	                              lv_label_set_text_fmt(g_sub,
1247	                                  "Fed %dg (today %d/%dg)", amount,
1248	                                  velapaw_store_today_total(m.id),
1249	                                  pet->daily_limit_g);
1250	                            }
1251	                        }
1252	                      else if (since < pet->cooldown_s)
1253	                        {
