  1..3 | ForEach-Object { $port.Write("`r`n"); Start-Sleep -Milliseconds 120 }
  Write-Output "waiting for launch..."
  $out = drain $port 8
  Write-Output $out
  if ($out -match 'LVGL ready') { Write-Output ">>> LAUNCH CONFIRMED <<<" } else { Write-Output ">>> retry needed <<<" }
} catch { Write-Output ("ERR: " + $_.Exception.Message) } finally { if ($port.IsOpen){$port.Close()} }

