1	/****************************************************************************
2	 * VelaPaw - V4L2 camera backend (emulator goldfish webcam / real sensor)
3	 *
4	 * Captures RGB565 frames from /dev/video and downscales (nearest) to
5	 * FRAME_W x FRAME_H RGB888 for the model + UI. Lets the user enroll a REAL
6	 * pet through the device camera instead of the embedded demo photos.
7	 *
8	 * Non-blocking: if no frame is ready, the last frame is returned (never
9	 * blocks the UI). On the emulator, goldfish_camera_initialize() registers
10	 * /dev/video (the vela bringup doesn't); flat build lets the app call it.
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	#include <sys/ioctl.h>
15	#include <fcntl.h>
16	#include <unistd.h>
17	#include <stdio.h>
18	#include <stdlib.h>
19	#include <string.h>
20	#include <errno.h>
21	
22	#include <nuttx/video/video.h>
23	#include <nuttx/video/v4l2_cap.h>
24	#ifdef CONFIG_GOLDFISH_CAMERA
25	#include <nuttx/video/goldfish_camera.h>
26	#endif
27	
28	#include "hal/camera.h"
29	
30	#ifdef CONFIG_VELAPAW_INFER_TFLM
31	#include "velapaw_assets.h"   /* embedded photos: fallback when no live camera */
32	#endif
33	
34	#define CAM_W       640
35	#define CAM_H       480
36	#define CAM_BUFNUM  3
37	
38	static int g_view;            /* fallback: which embedded pet is "in view" */
39	
40	static int       g_fd = -1;
41	static uint8_t  *g_buf[CAM_BUFNUM];
42	static size_t    g_bufsize;
43	static int       g_started;
44	static uint8_t   g_framebuf[VELAPAW_FRAME_BYTES];   /* zero (black) until 1st frame */
45	
46	/* Live camera ignores scenes; fallback uses it to pick the embedded pet. */
47	void velapaw_camera_mock_set_scene(int scene_id)
48	{
49	  g_view = scene_id;
50	}
51	
52	static int cam_qbuf(int index)
53	{
54	  struct v4l2_buffer b;
55	  memset(&b, 0, sizeof(b));
56	  b.type      = V4L2_BUF_TYPE_VIDEO_CAPTURE;
57	  b.memory    = V4L2_MEMORY_USERPTR;
58	  b.index     = index;
59	  b.m.userptr = (unsigned long)(uintptr_t)g_buf[index];
60	  b.length    = g_bufsize;
61	  return ioctl(g_fd, VIDIOC_QBUF, (uintptr_t)&b);
62	}
63	
64	int velapaw_camera_open(void)
65	{
66	#ifdef CONFIG_GOLDFISH_CAMERA
67	  int initret = goldfish_camera_initialize();
68	  printf("velapaw/cam: goldfish_camera_initialize -> %d\n", initret);
69	#endif
70	
71	  g_fd = open("/dev/video", O_RDWR);   /* O_NONBLOCK set after open (below) */
72	  if (g_fd < 0)
73	    {
74	      int e1 = errno;     /* EINVAL(22)=node exists but cam open rejected;
75	                           * ENOENT(2)=no camera registered (get_list==0) */
76	      g_fd = open("/dev/video0", O_RDWR);
77	      printf("velapaw/cam: open /dev/video errno=%d, /dev/video0 errno=%d\n",
78	             e1, (g_fd < 0) ? errno : 0);
79	    }
80	  if (g_fd < 0)
81	    {
82	      printf("velapaw/cam: no live camera; using embedded photos\n");
83	      return 0;   /* fall back to embedded photos in get_frame */
84	    }
85	
86	  int fl = fcntl(g_fd, F_GETFL, 0);
87	  if (fl >= 0)
88	    {
89	      fcntl(g_fd, F_SETFL, fl | O_NONBLOCK);   /* DQBUF returns EAGAIN, no hang */
90	    }
91	
92	  struct v4l2_format fmt;
93	  memset(&fmt, 0, sizeof(fmt));
94	  fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
95	  fmt.fmt.pix.width       = CAM_W;
96	  fmt.fmt.pix.height      = CAM_H;
97	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
98	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
99	  if (ioctl(g_fd, VIDIOC_S_FMT, (uintptr_t)&fmt) < 0)
100	    {
101	      printf("velapaw/cam: S_FMT RGB565 %dx%d failed (errno %d)\n",
102	             CAM_W, CAM_H, errno);
103	      close(g_fd); g_fd = -1; return 0; /* fall back to photos */
104	    }
105	
106	  struct v4l2_requestbuffers req;
107	  memset(&req, 0, sizeof(req));
108	  req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
109	  req.memory = V4L2_MEMORY_USERPTR;
110	  req.count  = CAM_BUFNUM;
111	  if (ioctl(g_fd, VIDIOC_REQBUFS, (uintptr_t)&req) < 0)
112	    {
113	      printf("velapaw/cam: REQBUFS failed (errno %d)\n", errno);
114	      close(g_fd); g_fd = -1; return 0; /* fall back to photos */
115	    }
116	
117	  g_bufsize = (size_t)CAM_W * CAM_H * 2;   /* RGB565 = 2 bytes/pixel */
118	  for (int i = 0; i < CAM_BUFNUM; i++)
119	    {
120	      g_buf[i] = (uint8_t *)memalign(32, g_bufsize);
121	      if (g_buf[i] == NULL || cam_qbuf(i) < 0)
122	        {
123	          printf("velapaw/cam: buffer %d setup failed (errno %d)\n", i, errno);
124	          close(g_fd); g_fd = -1; return 0; /* fall back to photos */
125	        }
126	    }
127	
128	  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
129	  if (ioctl(g_fd, VIDIOC_STREAMON, (uintptr_t)&type) < 0)
130	    {
131	      printf("velapaw/cam: STREAMON failed (errno %d)\n", errno);
132	      close(g_fd); g_fd = -1; return 0; /* fall back to photos */
133	    }
134	
135	  g_started = 1;
136	  printf("velapaw/cam: streaming %dx%d RGB565 from /dev/video\n", CAM_W, CAM_H);
137	  return 0;
138	}
139	
140	int velapaw_camera_get_frame(struct velapaw_frame *frame)
141	{
142	  if (frame == NULL)
143	    {
144	      return -1;
145	    }
146	
147	  if (g_fd >= 0)
148	    {
149	      struct v4l2_buffer b;
150	      memset(&b, 0, sizeof(b));
151	      b.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
152	      b.memory = V4L2_MEMORY_USERPTR;
153	      if (ioctl(g_fd, VIDIOC_DQBUF, (uintptr_t)&b) == 0)
154	        {
155	          const uint16_t *src = (const uint16_t *)(uintptr_t)g_buf[b.index];
156	
157	          for (int y = 0; y < VELAPAW_FRAME_H; y++)
158	            {
159	              int sy = y * CAM_H / VELAPAW_FRAME_H;
160	              for (int x = 0; x < VELAPAW_FRAME_W; x++)
161	                {
162	                  int sx = x * CAM_W / VELAPAW_FRAME_W;
163	                  uint16_t p = src[sy * CAM_W + sx];
164	                  uint8_t r = (p >> 11) & 0x1f;
165	                  uint8_t g = (p >> 5) & 0x3f;
166	                  uint8_t bl = p & 0x1f;
167	                  int o = (y * VELAPAW_FRAME_W + x) * 3;
168	                  g_framebuf[o + 0] = (uint8_t)((r << 3) | (r >> 2));
169	                  g_framebuf[o + 1] = (uint8_t)((g << 2) | (g >> 4));
170	                  g_framebuf[o + 2] = (uint8_t)((bl << 3) | (bl >> 2));
171	                }
172	            }
173	
174	          ioctl(g_fd, VIDIOC_QBUF, (uintptr_t)&b);   /* requeue */
175	        }
176	      /* else EAGAIN: no new frame -> return the previous g_framebuf */
177	    }
178	#ifdef CONFIG_VELAPAW_INFER_TFLM
179	  else
180	    {
181	      /* No live camera: serve the current view's embedded pet photo. */
182	      static int cur;
183	      int pet = (g_view >= 0 && g_view < VELAPAW_NUM_PETS) ? g_view : 0;
184	      int idxs[VELAPAW_NUM_IMAGES];
185	      int n = 0;
186	      for (int i = 0; i < VELAPAW_NUM_IMAGES; i++)
187	        {
188	          if (g_velapaw_image_pet[i] == pet)
189	            {
190	              idxs[n++] = i;
191	            }
192	        }
193	      int chosen = (n > 0) ? idxs[cur % n] : 0;
194	      cur++;
195	      memcpy(g_framebuf, g_velapaw_images[chosen], sizeof(g_framebuf));
196	    }
197	#endif
198	
199	  frame->data     = g_framebuf;
200	  frame->width    = VELAPAW_FRAME_W;
201	  frame->height   = VELAPAW_FRAME_H;
202	  frame->channels = VELAPAW_FRAME_C;
203	  return 0;
204	}
205	
206	void velapaw_camera_close(void)
207	{
208	  if (g_fd < 0)
209	    {
210	      return;
211	    }
212	  if (g_started)
213	    {
214	      enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
215	      ioctl(g_fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
216	      g_started = 0;
217	    }
218	  for (int i = 0; i < CAM_BUFNUM; i++)
219	    {
220	      free(g_buf[i]);
221	      g_buf[i] = NULL;
222	    }
223	  close(g_fd);
224	  g_fd = -1;
225	}
