41	esp_err_t camera_enable_out_clock(const camera_config_t* config)
42	{
43	    esp_err_t err = xclk_timer_conf(config->ledc_timer, config->xclk_freq_hz);
44	    if (err != ESP_OK) {
45	        ESP_LOGE(TAG, "ledc_timer_config failed, rc=%x", err);
46	        return err;
47	    }
48	
49	    g_ledc_channel = config->ledc_channel;
50	    ledc_channel_config_t ch_conf = {0};
51	    ch_conf.gpio_num = config->pin_xclk;
52	    ch_conf.speed_mode = LEDC_LOW_SPEED_MODE;
53	    ch_conf.channel = config->ledc_channel;
54	#if ESP_IDF_VERSION < ESP_IDF_VERSION_VAL(6,0,0)  
55	    // no need to explicitly configure interrupt, handled in the driver (IDF v6.0 and above)
56	    ch_conf.intr_type = LEDC_INTR_DISABLE; 
57	#endif
58	    ch_conf.timer_sel = config->ledc_timer;
59	    ch_conf.duty = 1;
60	    ch_conf.hpoint = 0;
61	    err = ledc_channel_config(&ch_conf);
62	    if (err != ESP_OK) {
63	        ESP_LOGE(TAG, "ledc_channel_config failed, rc=%x", err);
64	        return err;
65	    }
66	    return ESP_OK;
67	}
68	
69	void camera_disable_out_clock()
70	{
71	    if (g_ledc_channel != NO_CAMERA_LEDC_CHANNEL) {
72	        ledc_stop(LEDC_LOW_SPEED_MODE, g_ledc_channel, 0);
73	        g_ledc_channel = NO_CAMERA_LEDC_CHANNEL;
74	    }
75	}
