29	// support IDF 5.x
30	#ifndef portTICK_RATE_MS
31	#define portTICK_RATE_MS portTICK_PERIOD_MS
32	#endif
33	
34	#define SCCB_FREQ               CONFIG_SCCB_CLK_FREQ  /*!< I2C master frequency*/
35	#define WRITE_BIT               I2C_MASTER_WRITE      /*!< I2C master write */
36	#define READ_BIT                I2C_MASTER_READ       /*!< I2C master read */
37	#define ACK_CHECK_EN            0x1                   /*!< I2C master will check ack from slave*/
38	#define ACK_CHECK_DIS           0x0                   /*!< I2C master will not check ack from slave */
39	#define ACK_VAL                 0x0                   /*!< I2C ack value */
40	#define NACK_VAL                0x1                   /*!< I2C nack value */
41	#if CONFIG_SCCB_HARDWARE_I2C_PORT1
42	const int SCCB_I2C_PORT_DEFAULT = 1;
43	#else
44	const int SCCB_I2C_PORT_DEFAULT = 0;
45	#endif
46	
47	static int sccb_i2c_port;
48	static bool sccb_owns_i2c_port;
49	
50	int SCCB_Init(int pin_sda, int pin_scl)
51	{
52	    ESP_LOGI(TAG, "pin_sda %d pin_scl %d", pin_sda, pin_scl);
53	    i2c_config_t conf;
54	    esp_err_t ret;
55	
56	    memset(&conf, 0, sizeof(i2c_config_t));
57	
58	    sccb_i2c_port = SCCB_I2C_PORT_DEFAULT;
59	    sccb_owns_i2c_port = true;
60	    ESP_LOGI(TAG, "sccb_i2c_port=%d", sccb_i2c_port);
61	
62	    conf.mode = I2C_MODE_MASTER;
63	    conf.sda_io_num = pin_sda;
64	    conf.sda_pullup_en = GPIO_PULLUP_ENABLE;
65	    conf.scl_io_num = pin_scl;
66	    conf.scl_pullup_en = GPIO_PULLUP_ENABLE;
67	    conf.master.clk_speed = SCCB_FREQ;
68	
69	    if ((ret =  i2c_param_config(sccb_i2c_port, &conf)) != ESP_OK) {
70	        return ret;
71	    }
72	
73	    return i2c_driver_install(sccb_i2c_port, conf.mode, 0, 0, 0);
74	}
75	
76	int SCCB_Use_Port(int i2c_num) { // sccb use an already initialized I2C port
77	    if (sccb_owns_i2c_port) {
78	        SCCB_Deinit();
79	    }
80	    if (i2c_num < 0 || i2c_num > I2C_NUM_MAX) {
81	        return ESP_ERR_INVALID_ARG;
82	    }
83	    sccb_i2c_port = i2c_num;
84	    sccb_owns_i2c_port = false; // in this case, camera doesn't own the i2c port
85	    return ESP_OK;
86	}
87	
88	int SCCB_Deinit(void)
89	{
90	    if (!sccb_owns_i2c_port) {
91	        return ESP_OK;
92	    }
93	    sccb_owns_i2c_port = false;
94	    return i2c_driver_delete(sccb_i2c_port);
95	}
96	
97	int SCCB_Probe(uint8_t slv_addr)
98	{
99	    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
100	    i2c_master_start(cmd);
101	    i2c_master_write_byte(cmd, ( slv_addr << 1 ) | WRITE_BIT, ACK_CHECK_EN);
102	    i2c_master_stop(cmd);
103	    esp_err_t ret = i2c_master_cmd_begin(sccb_i2c_port, cmd, 1000 / portTICK_RATE_MS);
104	    i2c_cmd_link_delete(cmd);
105	    return ret;
106	}
107	
108	uint8_t SCCB_Read(uint8_t slv_addr, uint8_t reg)
109	{
110	    uint8_t data=0;
111	    esp_err_t ret = ESP_FAIL;
112	    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
113	    i2c_master_start(cmd);
114	    i2c_master_write_byte(cmd, ( slv_addr << 1 ) | WRITE_BIT, ACK_CHECK_EN);
115	    i2c_master_write_byte(cmd, reg, ACK_CHECK_EN);
116	    i2c_master_stop(cmd);
117	    ret = i2c_master_cmd_begin(sccb_i2c_port, cmd, 1000 / portTICK_RATE_MS);
118	    i2c_cmd_link_delete(cmd);
119	    if(ret != ESP_OK) return -1;
120	    cmd = i2c_cmd_link_create();
121	    i2c_master_start(cmd);
122	    i2c_master_write_byte(cmd, ( slv_addr << 1 ) | READ_BIT, ACK_CHECK_EN);
123	    i2c_master_read_byte(cmd, &data, NACK_VAL);
124	    i2c_master_stop(cmd);
125	    ret = i2c_master_cmd_begin(sccb_i2c_port, cmd, 1000 / portTICK_RATE_MS);
126	    i2c_cmd_link_delete(cmd);
127	    if(ret != ESP_OK) {
128	        ESP_LOGE(TAG, "SCCB_Read Failed addr:0x%02x, reg:0x%02x, data:0x%02x, ret:%d", slv_addr, reg, data, ret);
129	    }
130	    return data;
131	}
132	
133	int SCCB_Write(uint8_t slv_addr, uint8_t reg, uint8_t data)
134	{
135	    esp_err_t ret = ESP_FAIL;
136	    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
137	    i2c_master_start(cmd);
138	    i2c_master_write_byte(cmd, ( slv_addr << 1 ) | WRITE_BIT, ACK_CHECK_EN);
139	    i2c_master_write_byte(cmd, reg, ACK_CHECK_EN);
140	    i2c_master_write_byte(cmd, data, ACK_CHECK_EN);
141	    i2c_master_stop(cmd);
142	    ret = i2c_master_cmd_begin(sccb_i2c_port, cmd, 1000 / portTICK_RATE_MS);
143	    i2c_cmd_link_delete(cmd);
144	    if(ret != ESP_OK) {
145	        ESP_LOGE(TAG, "SCCB_Write Failed addr:0x%02x, reg:0x%02x, data:0x%02x, ret:%d", slv_addr, reg, data, ret);
146	    }
147	    return ret == ESP_OK ? 0 : -1;
148	}
