150	uint8_t SCCB_Read16(uint8_t slv_addr, uint16_t reg)
151	{
152	    uint8_t data=0;
153	    esp_err_t ret = ESP_FAIL;
154	    uint16_t reg_htons = LITTLETOBIG(reg);
155	    uint8_t *reg_u8 = (uint8_t *)&reg_htons;
156	    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
157	    i2c_master_start(cmd);
158	    i2c_master_write_byte(cmd, ( slv_addr << 1 ) | WRITE_BIT, ACK_CHECK_EN);
159	    i2c_master_write_byte(cmd, reg_u8[0], ACK_CHECK_EN);
160	    i2c_master_write_byte(cmd, reg_u8[1], ACK_CHECK_EN);
161	    i2c_master_stop(cmd);
162	    ret = i2c_master_cmd_begin(sccb_i2c_port, cmd, 1000 / portTICK_RATE_MS);
163	    i2c_cmd_link_delete(cmd);
164	    if(ret != ESP_OK) return -1;
165	    cmd = i2c_cmd_link_create();
166	    i2c_master_start(cmd);
167	    i2c_master_write_byte(cmd, ( slv_addr << 1 ) | READ_BIT, ACK_CHECK_EN);
168	    i2c_master_read_byte(cmd, &data, NACK_VAL);
169	    i2c_master_stop(cmd);
170	    ret = i2c_master_cmd_begin(sccb_i2c_port, cmd, 1000 / portTICK_RATE_MS);
171	    i2c_cmd_link_delete(cmd);
172	    if(ret != ESP_OK) {
173	        ESP_LOGE(TAG, "W [%04x]=%02x fail\n", reg, data);
174	    }
175	    return data;
176	}
177	
178	int SCCB_Write16(uint8_t slv_addr, uint16_t reg, uint8_t data)
179	{
180	    static uint16_t i = 0;
181	    esp_err_t ret = ESP_FAIL;
182	    uint16_t reg_htons = LITTLETOBIG(reg);
183	    uint8_t *reg_u8 = (uint8_t *)&reg_htons;
184	    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
185	    i2c_master_start(cmd);
186	    i2c_master_write_byte(cmd, ( slv_addr << 1 ) | WRITE_BIT, ACK_CHECK_EN);
187	    i2c_master_write_byte(cmd, reg_u8[0], ACK_CHECK_EN);
188	    i2c_master_write_byte(cmd, reg_u8[1], ACK_CHECK_EN);
189	    i2c_master_write_byte(cmd, data, ACK_CHECK_EN);
190	    i2c_master_stop(cmd);
