1	/* Waveshare ESP32-S3-Touch-LCD-3.5: ST7796 lcd_dev, unified shadow bit-bang. */
2	#include <nuttx/config.h>
3	#include <stdint.h>
4	#include <stdbool.h>
5	#include <errno.h>
6	#include <syslog.h>
7	#include <nuttx/arch.h>
