9	#include <nuttx/i2c/i2c_master.h>
10	#include <nuttx/video/fb.h>
11	#include <nuttx/lcd/lcd.h>
12	#include <nuttx/ioexpander/ioexpander.h>
13	#include <nuttx/ioexpander/pca9557.h>
14	#include "esp32s3_i2c.h"
15	#include "esp32s3_gpio.h"
16	#include <nuttx/input/ft5x06.h>
17	
18	#define PIN_MOSI 1
19	#define PIN_CLK  5
20	#define PIN_DC   3
21	#define PIN_BL   6
22	#define XRES 480
23	#define YRES 320
24	#define MOSI_M (1U<<PIN_MOSI)
25	#define CLK_M  (1U<<PIN_CLK)
26	#define DC_M   (1U<<PIN_DC)
27	#define REG_OUT 0x60004004U
28	static inline void wreg(uint32_t a, uint32_t v){ *(volatile uint32_t *)a = v; }
29	static uint32_t g_out;   /* shadow: BL(+others) set, MOSI/CLK/DC cleared */
30	
31	struct wslcd_s { struct lcd_dev_s dev; int power; uint16_t runbuf[XRES]; };
32	static struct wslcd_s g_lcd;
33	static struct pca9557_config_s g_tca = { 0x20, 100000, NULL };
34	
35	static int axp_wr(struct i2c_master_s *i,uint8_t r,uint8_t v){struct i2c_msg_s m;uint8_t b[2];b[0]=r;b[1]=v;m.frequency=400000;m.addr=0x34;m.flags=0;m.buffer=b;m.length=2;return I2C_TRANSFER(i,&m,1);}
36	static void axp_power(struct i2c_master_s *i){axp_wr(i,0x80,0x01);axp_wr(i,0x82,(3300-1500)/100);axp_wr(i,0x90,0x00);axp_wr(i,0x91,0x00);nxsig_usleep(5000);axp_wr(i,0x92,(3300-500)/100);axp_wr(i,0x96,(1500-500)/100);axp_wr(i,0x97,(2800-500)/100);axp_wr(i,0x90,0x31);nxsig_usleep(120000);}
37	
38	/* unified shadow bit-bang: always ends CLK low; D/C carried in the shadow */
39	static inline void clock_byte(uint8_t b, uint32_t base)
40	{ int i; for(i=0;i<8;i++){ uint32_t o=base|((b&0x80)?MOSI_M:0); b<<=1; wreg(REG_OUT,o); wreg(REG_OUT,o|CLK_M);} }
41	static void cmd(uint8_t c){ uint32_t base=g_out;       wreg(REG_OUT,base); clock_byte(c,base); wreg(REG_OUT,base); }
42	static void dat(uint8_t d){ uint32_t base=g_out|DC_M;  wreg(REG_OUT,base); clock_byte(d,base); wreg(REG_OUT,base); }
43	static void bb_window(int x0,int x1,int y0,int y1){
44	  cmd(0x2A);dat(x0>>8);dat(x0&0xff);dat(x1>>8);dat(x1&0xff);
45	  cmd(0x2B);dat(y0>>8);dat(y0&0xff);dat(y1>>8);dat(y1&0xff);
46	  cmd(0x2C);
47	}
48	static void fill_be(uint8_t hi,uint8_t lo,long npix){ uint32_t base=g_out|DC_M; long n; for(n=0;n<npix;n++){clock_byte(hi,base);clock_byte(lo,base);} wreg(REG_OUT,base); }
49	
50	static void panel_init(void)
51	{
52	  esp32s3_configgpio(PIN_MOSI,OUTPUT);esp32s3_configgpio(PIN_CLK,OUTPUT);esp32s3_configgpio(PIN_DC,OUTPUT);
53	  g_out=(*(volatile uint32_t *)REG_OUT)&~(MOSI_M|CLK_M|DC_M);
54	  cmd(0x01);up_mdelay(150);cmd(0x11);up_mdelay(120);
55	  cmd(0xF0);dat(0xC3);cmd(0xF0);dat(0x96);cmd(0x36);dat(0x28);cmd(0x3A);dat(0x55);
56	  cmd(0xF0);dat(0x3C);cmd(0xF0);dat(0x69);cmd(0x21);cmd(0x29);up_mdelay(120);
57	  bb_window(0,XRES-1,0,YRES-1); fill_be(0,0,(long)XRES*YRES);
58	  syslog(LOG_ERR,"[wslcd] panel_init done\n");
59	}
60	
61	static int lcd_getvideoinfo(struct lcd_dev_s *dev, struct fb_videoinfo_s *v)
62	{ v->fmt=FB_FMT_RGB16_565; v->xres=XRES; v->yres=YRES; v->nplanes=1; return OK; }
63	
64	static int lcd_putarea(struct lcd_dev_s *dev, fb_coord_t rs, fb_coord_t re, fb_coord_t cs, fb_coord_t ce, const uint8_t *buffer, fb_coord_t stride)
65	{
66	  uint32_t base; int rows=re-rs+1, r; size_t rowb=(size_t)(ce-cs+1)*2, i;
67	  bb_window(cs, ce, rs, re);
68	  base=g_out|DC_M;
69	  for(r=0;r<rows;r++){ const uint8_t *p=buffer+(size_t)r*stride; for(i=0;i<rowb;i+=2){clock_byte(p[i+1],base);clock_byte(p[i],base);} }
70	  wreg(REG_OUT, base);
71	  return OK;
72	}
73	static int lcd_putrun(struct lcd_dev_s *dev, fb_coord_t row, fb_coord_t col, const uint8_t *buffer, size_t npixels)
74	{
75	  uint32_t base; size_t i;
76	  bb_window(col, col+npixels-1, row, row);
77	  base=g_out|DC_M;
78	  for(i=0;i<npixels*2;i+=2){clock_byte(buffer[i+1],base);clock_byte(buffer[i],base);}
79	  wreg(REG_OUT, base);
80	  return OK;
81	}
82	#ifndef CONFIG_LCD_NOGETRUN
83	static int lcd_getrun(struct lcd_dev_s *dev, fb_coord_t row, fb_coord_t col, uint8_t *buffer, size_t npixels){ return -ENOSYS; }
84	#endif
85	static int lcd_getplaneinfo(struct lcd_dev_s *dev, unsigned int planeno, struct lcd_planeinfo_s *p)
86	{ p->putrun=lcd_putrun; p->putarea=lcd_putarea;
87	#ifndef CONFIG_LCD_NOGETRUN
88	  p->getrun=lcd_getrun;
89	#endif
90	  p->buffer=(uint8_t *)g_lcd.runbuf; p->bpp=16; p->dev=dev; return OK; }
91	static int lcd_getpower(struct lcd_dev_s *dev){ return g_lcd.power; }
92	static int lcd_setpower(struct lcd_dev_s *dev, int power){ g_lcd.power=power; esp32s3_gpiowrite(PIN_BL, power>0); return OK; }
93	
94	static void ts_wakeup(const struct ft5x06_config_s *c){(void)c;}
95	static void ts_nreset(const struct ft5x06_config_s *c, bool st){(void)c;(void)st;}
96	static const struct ft5x06_config_s g_ts = {
97	  .address=0x38, .frequency=400000, .wakeup=ts_wakeup, .nreset=ts_nreset,
98	};
99	
100	int board_lcd_initialize(void)
101	{
102	  struct i2c_master_s *i2c; struct ioexpander_dev_s *ioe;
103	  syslog(LOG_ERR,"[wslcd] init\n");
104	  esp32s3_configgpio(PIN_BL,OUTPUT);esp32s3_gpiowrite(PIN_BL,true);
105	  i2c=esp32s3_i2cbus_initialize(0);
106	  if(i2c){axp_power(i2c);ioe=pca9557_initialize(i2c,&g_tca);
107	    if(ioe){IOEXP_SETDIRECTION(ioe,0,IOEXPANDER_DIRECTION_OUT);IOEXP_SETDIRECTION(ioe,1,IOEXPANDER_DIRECTION_OUT);
108	      IOEXP_WRITEPIN(ioe,0,false);IOEXP_WRITEPIN(ioe,1,false);nxsig_usleep(100000);
109	      IOEXP_WRITEPIN(ioe,1,true);nxsig_usleep(120000);} {struct i2c_msg_s _m[2]; uint8_t _r=0xA3,_id=0xFF; int _ret;
110	 _m[0].frequency=400000;_m[0].addr=0x38;_m[0].flags=0;_m[0].buffer=&_r;_m[0].length=1;
111	 _m[1].frequency=400000;_m[1].addr=0x38;_m[1].flags=I2C_M_READ;_m[1].buffer=&_id;_m[1].length=1;
112	 _ret=I2C_TRANSFER(i2c,_m,2);
113	 syslog(LOG_ERR,"[wslcd] FT6336 id(0xA3)=0x%02x ret=%d\n",_id,_ret);}
114	 ft5x06_register(i2c,&g_ts,0); syslog(LOG_ERR,"[wslcd] touch registered\n");}
115	  panel_init();
116	  g_lcd.dev.getvideoinfo=lcd_getvideoinfo;
117	  g_lcd.dev.getplaneinfo=lcd_getplaneinfo;
118	  g_lcd.dev.getpower=lcd_getpower;
119	  g_lcd.dev.setpower=lcd_setpower;
120	  g_lcd.power=1;
121	  return OK;
122	}
123	struct lcd_dev_s *board_lcd_getdev(int devno){ return &g_lcd.dev; }
124	void board_lcd_uninitialize(void){}
