  1..2 | ForEach-Object { $port.Write("`r`n"); Start-Sleep -Milliseconds 150 }
  [void](drain $port 1)
  foreach($ch in "dmesg".ToCharArray()){ $port.Write([string]$ch); Start-Sleep -Milliseconds 45 }
  Start-Sleep -Milliseconds 150; $port.Write("`r"); Start-Sleep -Milliseconds 80; $port.Write("`n")
  $out = drain $port 4
  Write-Output "=== dmesg ==="; Write-Output $out
} catch { Write-Output ("ERR: " + $_.Exception.Message) } finally { if ($port.IsOpen){$port.Close()} }

