98	static void CAMERA_ISR_IRAM_ATTR ll_cam_vsync_isr(void *arg)
99	{
100	    //DBG_PIN_SET(1);
101	    cam_obj_t *cam = (cam_obj_t *)arg;
102	    BaseType_t HPTaskAwoken = pdFALSE;
103	
104	    typeof(LCD_CAM.lc_dma_int_st) status = LCD_CAM.lc_dma_int_st;
105	    if (status.val == 0) {
106	        return;
107	    }
108	
109	    LCD_CAM.lc_dma_int_clr.val = status.val;
110	
111	    if (status.cam_vsync_int_st) {
112	        ll_cam_send_event(cam, CAM_VSYNC_EVENT, &HPTaskAwoken);
113	    }
114	
115	    if (HPTaskAwoken == pdTRUE) {
116	        portYIELD_FROM_ISR();
117	    }
118	    //DBG_PIN_SET(0);
119	}
