121	static void CAMERA_ISR_IRAM_ATTR ll_cam_dma_isr(void *arg)
122	{
123	    cam_obj_t *cam = (cam_obj_t *)arg;
124	    BaseType_t HPTaskAwoken = pdFALSE;
125	
126	    typeof(GDMA.channel[cam->dma_num].in.int_st) status = GDMA.channel[cam->dma_num].in.int_st;
127	    if (status.val == 0) {
128	        return;
129	    }
130	
131	    GDMA.channel[cam->dma_num].in.int_clr.val = status.val;
132	
133	    if (status.in_suc_eof) {
134	        ll_cam_send_event(cam, CAM_IN_SUC_EOF_EVENT, &HPTaskAwoken);
135	    }
136	
137	    if (HPTaskAwoken == pdTRUE) {
138	        portYIELD_FROM_ISR();
139	    }
140	}
