152	bool ll_cam_start(cam_obj_t *cam, int frame_pos)
153	{
154	    LCD_CAM.cam_ctrl1.cam_start = 0;
155	
156	    if (cam->jpeg_mode || !cam->psram_mode) {
157	        GDMA.channel[cam->dma_num].in.int_clr.in_suc_eof = 1;
158	        GDMA.channel[cam->dma_num].in.int_ena.in_suc_eof = 1;
159	    }
160	
161	    LCD_CAM.cam_ctrl1.cam_reset = 1;
162	    LCD_CAM.cam_ctrl1.cam_reset = 0;
163	    LCD_CAM.cam_ctrl1.cam_afifo_reset = 1;
164	    LCD_CAM.cam_ctrl1.cam_afifo_reset = 0;
165	    GDMA.channel[cam->dma_num].in.conf0.in_rst = 1;
166	    GDMA.channel[cam->dma_num].in.conf0.in_rst = 0;
167	
168	    LCD_CAM.cam_ctrl1.cam_rec_data_bytelen = cam->dma_half_buffer_size - 1; // Ping pong operation
169	
170	    if (!cam->psram_mode) {
171	        GDMA.channel[cam->dma_num].in.link.addr = ((uint32_t)&cam->dma[0]) & 0xfffff;
172	    } else {
173	        GDMA.channel[cam->dma_num].in.link.addr = ((uint32_t)&cam->frames[frame_pos].dma[0]) & 0xfffff;
174	    }
175	
176	    GDMA.channel[cam->dma_num].in.link.start = 1;
177	
178	    LCD_CAM.cam_ctrl.cam_update = 1;
179	    LCD_CAM.cam_ctrl1.cam_start = 1;
180	    return true;
181	}
