183	esp_err_t ll_cam_deinit(cam_obj_t *cam)
184	{
185	    if (cam->cam_intr_handle) {
186	        esp_intr_free(cam->cam_intr_handle);
187	        cam->cam_intr_handle = NULL;
188	    }
189	
190	    if (cam->dma_intr_handle) {
191	        esp_intr_free(cam->dma_intr_handle);
192	        cam->dma_intr_handle = NULL;
193	    }
194	    if (cam->dma_channel_handle) {
195	        // gdma_disconnect(cam->dma_channel_handle); // not needed since code never calls gdma_connect() to connect channel to peripheral
196	        gdma_del_channel(cam->dma_channel_handle);
197	        cam->dma_channel_handle = NULL;
198	        // GDMA.channel[cam->dma_num].in.link.addr = 0x0;
199	    }
200	    LCD_CAM.cam_ctrl1.cam_start = 0;
201	    LCD_CAM.cam_ctrl1.cam_reset = 1;
202	    LCD_CAM.cam_ctrl1.cam_reset = 0;
203	    return ESP_OK;
204	}
