384	esp_err_t ll_cam_set_pin(cam_obj_t *cam, const camera_config_t *config)
385	{
386	    PIN_FUNC_SELECT(GPIO_PIN_MUX_REG[config->pin_pclk], PIN_FUNC_GPIO);
387	    gpio_set_direction(config->pin_pclk, GPIO_MODE_INPUT);
388	    gpio_set_pull_mode(config->pin_pclk, GPIO_FLOATING);
389	    gpio_matrix_in(config->pin_pclk, CAM_PCLK_IDX, false);
390	
391	    PIN_FUNC_SELECT(GPIO_PIN_MUX_REG[config->pin_vsync], PIN_FUNC_GPIO);
392	    gpio_set_direction(config->pin_vsync, GPIO_MODE_INPUT);
393	    gpio_set_pull_mode(config->pin_vsync, GPIO_FLOATING);
394	    gpio_matrix_in(config->pin_vsync, CAM_V_SYNC_IDX, cam->vsync_invert);
395	
396	    PIN_FUNC_SELECT(GPIO_PIN_MUX_REG[config->pin_href], PIN_FUNC_GPIO);
397	    gpio_set_direction(config->pin_href, GPIO_MODE_INPUT);
398	    gpio_set_pull_mode(config->pin_href, GPIO_FLOATING);
399	    gpio_matrix_in(config->pin_href, CAM_H_ENABLE_IDX, false);
400	
401	    int data_pins[8] = {
402	        config->pin_d0, config->pin_d1, config->pin_d2, config->pin_d3, config->pin_d4, config->pin_d5, config->pin_d6, config->pin_d7,
403	    };
404	    for (int i = 0; i < 8; i++) {
405	        PIN_FUNC_SELECT(GPIO_PIN_MUX_REG[data_pins[i]], PIN_FUNC_GPIO);
406	        gpio_set_direction(data_pins[i], GPIO_MODE_INPUT);
407	        gpio_set_pull_mode(data_pins[i], GPIO_FLOATING);
408	        gpio_matrix_in(data_pins[i], CAM_DATA_IN0_IDX + i, false);
409	    }
410	    if (config->pin_xclk >= 0) { 
411	        PIN_FUNC_SELECT(GPIO_PIN_MUX_REG[config->pin_xclk], PIN_FUNC_GPIO);
412	        gpio_set_direction(config->pin_xclk, GPIO_MODE_OUTPUT);
413	        gpio_set_pull_mode(config->pin_xclk, GPIO_FLOATING);
414	        gpio_matrix_out(config->pin_xclk, CAM_CLK_IDX, false, false);
415	    }
416	
417	    return ESP_OK;
