540	        if (cam->psram_mode) {
541	            cam->dma_buffer_size = cam->recv_size;
542	            cam->dma_half_buffer_size = 1024;
543	            cam->dma_half_buffer_cnt = cam->dma_buffer_size / cam->dma_half_buffer_size;
