312	static int set_image_options(sensor_t *sensor)
313	{
314	    int ret = 0;
315	    uint8_t reg20 = 0;
316	    uint8_t reg21 = 0;
317	    uint8_t reg4514 = 0;
318	    uint8_t reg4514_test = 0;
319	
