338	    }
339	
340	    // H-Mirror
341	    if (sensor->status.hmirror) {
342	        reg21 |= 0x06;
343	        reg4514_test |= 2;
344	    }
345	
346	    switch (reg4514_test) {
347	        //no binning
348	        case 0: reg4514 = 0x88; break;//normal
349	        case 1: reg4514 = 0x00; break;//v-flip
350	        case 2: reg4514 = 0xbb; break;//h-mirror
351	        case 3: reg4514 = 0x00; break;//v-flip+h-mirror
352	        //binning
353	        case 4: reg4514 = 0xaa; break;//normal
354	        case 5: reg4514 = 0xbb; break;//v-flip
355	        case 6: reg4514 = 0xbb; break;//h-mirror
356	        case 7: reg4514 = 0xaa; break;//v-flip+h-mirror
357	    }
358	
359	    if(write_reg(sensor->slv_addr, TIMING_TC_REG20, reg20)
360	        || write_reg(sensor->slv_addr, TIMING_TC_REG21, reg21)
361	        || write_reg(sensor->slv_addr, 0x4514, reg4514)){
362	        ESP_LOGE(TAG, "Setting Image Options Failed");
363	        return -1;
364	    }
365	
366	    if (!sensor->status.binning) {
367	        ret  = write_reg(sensor->slv_addr, 0x4520, 0x10)
368	            || write_reg(sensor->slv_addr, X_INCREMENT, 0x11)//odd:1, even: 1
369	            || write_reg(sensor->slv_addr, Y_INCREMENT, 0x11);//odd:1, even: 1
