308	static void cam_lcdcam_init(void)
309	{
310	  /* enable LCD_CAM peripheral clock + release reset */
311	  sreg(R_SYS_CLK_EN1, B_SYS_LCDCAM);
312	  creg(R_SYS_RST_EN1, B_SYS_LCDCAM);
313	  /* CAM_CTRL: clk_sel=3, clkm_div_num=8 (160/20), vsync_filter_thres=4,
314	   * vs_eof_en=1: since capture is armed at a frame START (cam_wait_vsync),
315	   * the DMA runs to the NEXT VSYNC = exactly one aligned frame. */
316	  wreg(R_CAM_CTRL, (3u<<29) | (8u<<9) | (4u<<1) | B_CAM_VS_EOF_EN);
317	  /* CAM_CTRL1: rec_data_bytelen max, vsync_filter_en, 8-bit data */
318	  wreg(R_CAM_CTRL1, 0xffffu | B_CAM_VSFILT_EN);
319	  wreg(R_CAM_RGB_YUV, 0);

319	  wreg(R_CAM_RGB_YUV, 0);
