167	    }
168	  int n    = frame->width * frame->height * frame->channels;
169	  int in_n = g_input->bytes;
170	  for (int i = 0; i < n && i < in_n; i++)
171	    {
172	      float norm = ((float)frame->data[i] - 127.5f) / 127.5f;
173	      int q = (int)lroundf(norm / in_scale) + in_zp;
174	      if (q < -128) q = -128;
175	      if (q > 127)  q = 127;
176	      g_input->data.int8[i] = (int8_t)q;
177	    }
