181	  clock_gettime(CLOCK_MONOTONIC, &t0);
182	  TfLiteStatus status = g_interp->Invoke();
183	  clock_gettime(CLOCK_MONOTONIC, &t1);
184	  g_last_us = elapsed_us(&t0, &t1);
