  for (uint32_t i = 0; i < n; i++) s += model_buf[i];
  printf("tflm: sum32=%08x (want 0a5e8f6d) b32=%02x(14) b1k=%02x(00) b500k=%02x(f1) blast=%02x(03)\n",
         (unsigned)s, model_buf[32], model_buf[1000], model_buf[500000],
         model_buf[n - 1]); fflush(stdout);
}
printf("tflm: GetModel...\n"); fflush(stdout);
