1	/****************************************************************************
2	 * VelaPaw - enrollment store + cosine matcher (in-memory)
3	 *
4	 * Persistence is delegated to store/ (stub for now). Embeddings are assumed
5	 * L2-normalized, so cosine similarity == dot product.
6	 ****************************************************************************/
7	
8	#include <string.h>
9	#include <math.h>
10	#include "identity/identity.h"
11	
12	static struct velapaw_pet g_pets[VELAPAW_MAX_PETS];
13	static int                g_npets;
14	
15	void velapaw_identity_init(void)
16	{
17	  memset(g_pets, 0, sizeof(g_pets));
18	  g_npets = 0;
19	}
20	
21	int velapaw_identity_count(void)
22	{
23	  return g_npets;
24	}
25	
26	const struct velapaw_pet *velapaw_identity_get(velapaw_pet_id_t id)
27	{
28	  if (id < 0 || id >= g_npets)
29	    {
30	      return NULL;
31	    }
32	
33	  return &g_pets[id];
34	}
35	
36	velapaw_pet_id_t velapaw_identity_enroll(
37	    const char *name, int portion_g, int cooldown_s, int daily_limit_g,
38	    const float (*samples)[VELAPAW_EMBED_DIM], int n_samples)
39	{
40	  if (g_npets >= VELAPAW_MAX_PETS || samples == NULL || n_samples <= 0)
41	    {
42	      return VELAPAW_PET_UNKNOWN;
43	    }
44	
45	  struct velapaw_pet *p = &g_pets[g_npets];
46	
47	  p->id            = g_npets;
48	  p->portion_g     = portion_g;
49	  p->cooldown_s    = cooldown_s;
50	  p->daily_limit_g = daily_limit_g;
51	  p->samples_n     = n_samples;
52	  strncpy(p->name, name ? name : "pet", VELAPAW_NAME_MAX - 1);
53	  p->name[VELAPAW_NAME_MAX - 1] = '\0';
54	
55	  /* Average the sample embeddings. */
56	  for (int d = 0; d < VELAPAW_EMBED_DIM; d++)
57	    {
58	      float acc = 0.0f;
59	      for (int s = 0; s < n_samples; s++)
60	        {
61	          acc += samples[s][d];
62	        }
63	
64	      p->embedding[d] = acc / (float)n_samples;
65	    }
66	
67	  /* Re-normalize the averaged centroid. */
68	  float norm = 0.0f;
69	  for (int d = 0; d < VELAPAW_EMBED_DIM; d++)
70	    {
71	      norm += p->embedding[d] * p->embedding[d];
72	    }
73	
74	  norm = sqrtf(norm);
75	  if (norm < 1e-6f)
76	    {
77	      norm = 1.0f;
78	    }
79	
80	  for (int d = 0; d < VELAPAW_EMBED_DIM; d++)
81	    {
82	      p->embedding[d] /= norm;
83	    }
84	
85	  return g_pets[g_npets++].id;
86	}
87	
88	void velapaw_identity_match(const float *embedding, struct velapaw_match *out)
89	{
90	  if (out == NULL)
91	    {
92	      return;
93	    }
94	
95	  out->id     = VELAPAW_PET_UNKNOWN;
96	  out->score  = -1.0f;
97	  out->margin = 0.0f;
98	
99	  if (embedding == NULL || g_npets == 0)
100	    {
101	      return;
102	    }
103	
104	  float best = -1.0f;
105	  float second = -1.0f;
106	  velapaw_pet_id_t best_id = VELAPAW_PET_UNKNOWN;
107	
108	  for (int i = 0; i < g_npets; i++)
109	    {
110	      float dot = 0.0f;
111	      for (int d = 0; d < VELAPAW_EMBED_DIM; d++)
112	        {
113	          dot += embedding[d] * g_pets[i].embedding[d];
114	        }
115	
116	      if (dot > best)
117	        {
118	          second  = best;
119	          best    = dot;
120	          best_id = g_pets[i].id;
121	        }
122	      else if (dot > second)
123	        {
124	          second = dot;
125	        }
126	    }
127	
128	  out->score  = best;
129	  out->margin = (second > -1.0f) ? (best - second) : best;
130	
131	  if (best >= VELAPAW_MATCH_THRESHOLD)
132	    {
133	      out->id = best_id;
134	    }
135	}
