1	/****************************************************************************
2	 * VelaPaw - in-memory store backend (emulator) + feeding-behavior analytics
3	 *
4	 * Keeps a rolling 7-day history of grams + meal counts per pet (index
5	 * DAYS-1 == today). Powers daily/weekly intake, meal frequency, appetite
6	 * baseline/trend, and the sudden-appetite-drop alert. Replace with a
7	 * persistent backend (apps/system/settings or littlefs) on hardware so
8	 * history survives reboots.
9	 ****************************************************************************/
10	
11	#include <stdio.h>
12	#include <string.h>
13	#include "store/store.h"
14	
15	#define DAYS VELAPAW_HIST_DAYS
16	#define TODAY (DAYS - 1)
17	
18	static int g_day_g[VELAPAW_MAX_PETS][DAYS];      /* grams per day */
19	static int g_day_m[VELAPAW_MAX_PETS][DAYS];      /* meals per day */
20	static int g_bcs[VELAPAW_MAX_PETS];              /* last BCS: 0/1/2, -1 none */
21	
22	static int valid(velapaw_pet_id_t id)
23	{
24	  return id >= 0 && id < VELAPAW_MAX_PETS;
25	}
26	
27	int velapaw_store_init(void)
28	{
29	  memset(g_day_g, 0, sizeof(g_day_g));
30	  memset(g_day_m, 0, sizeof(g_day_m));
31	  for (int i = 0; i < VELAPAW_MAX_PETS; i++)
32	    {
33	      g_bcs[i] = -1;
34	    }
35	  return 0;
36	}
37	
38	int velapaw_store_log_feeding(const struct velapaw_feed_event *ev)
39	{
40	  if (ev == NULL || !valid(ev->pet_id))
41	    {
42	      return -1;
43	    }
44	
45	  g_day_g[ev->pet_id][TODAY] += ev->grams;
46	  g_day_m[ev->pet_id][TODAY] += 1;
47	
48	  printf("    [store] event pet=%d grams=%d score=%.2f model=%s\n",
49	         ev->pet_id, ev->grams, ev->score, ev->model ? ev->model : "?");
50	  return 0;
51	}
52	
53	int velapaw_store_today_total(velapaw_pet_id_t id)
54	{
55	  return valid(id) ? g_day_g[id][TODAY] : 0;
56	}
57	
58	int velapaw_store_today_meals(velapaw_pet_id_t id)
59	{
60	  return valid(id) ? g_day_m[id][TODAY] : 0;
61	}
62	
63	int velapaw_store_week_total(velapaw_pet_id_t id)
64	{
65	  if (!valid(id))
66	    {
67	      return 0;
68	    }
69	  int sum = 0;
70	  for (int d = 0; d < VELAPAW_WEEK_DAYS && d <= TODAY; d++)
71	    {
72	      sum += g_day_g[id][TODAY - d];   /* last 7 days incl. today */
73	    }
74	  return sum;
75	}
76	
77	int velapaw_store_month_total(velapaw_pet_id_t id)
78	{
79	  if (!valid(id))
80	    {
81	      return 0;
82	    }
83	  int sum = 0;
84	  for (int d = 0; d < DAYS; d++)
85	    {
86	      sum += g_day_g[id][d];
87	    }
88	  return sum;
89	}
90	
91	int velapaw_store_day_total(velapaw_pet_id_t id, int day_back)
92	{
93	  if (!valid(id) || day_back < 0 || day_back >= DAYS)
94	    {
95	      return 0;
96	    }
97	  return g_day_g[id][TODAY - day_back];
98	}
99	
100	/* average of the prior days (everything except today) */
101	int velapaw_store_baseline_g(velapaw_pet_id_t id)
102	{
103	  if (!valid(id))
104	    {
105	      return 0;
106	    }
107	  int sum = 0;
108	  for (int d = 0; d < TODAY; d++)
109	    {
110	      sum += g_day_g[id][d];
111	    }
112	  return sum / (DAYS - 1);
113	}
114	
115	int velapaw_store_appetite_pct(velapaw_pet_id_t id)
116	{
117	  int base = velapaw_store_baseline_g(id);
118	  if (base <= 0)
119	    {
120	      return 100;
121	    }
122	  return g_day_g[id][TODAY] * 100 / base;
123	}
124	
125	/* Alert on the most recent *completed* day (yesterday = TODAY-1) vs the
126	 * baseline of the days before it: a >50% drop is the early illness sign.
127	 */
128	int velapaw_store_alert_drop(velapaw_pet_id_t id)
129	{
130	  if (!valid(id) || DAYS < 3)
131	    {
132	      return 0;
133	    }
134	  int last = g_day_g[id][TODAY - 1];
135	  int sum = 0;
136	  for (int d = 0; d < TODAY - 1; d++)
137	    {
138	      sum += g_day_g[id][d];
139	    }
140	  int base = sum / (DAYS - 2);
141	  return (base > 0 && last * 2 < base) ? 1 : 0;
142	}
143	
144	void velapaw_store_seed(velapaw_pet_id_t id, int daily_g)
145	{
146	  if (!valid(id) || daily_g <= 0)
147	    {
148	      return;
149	    }
150	  /* fill the prior days with a normal baseline (deterministic +/- noise);
151	   * leave today (TODAY) at 0 so live feeding fills it in.
152	   */
153	  for (int d = 0; d < TODAY; d++)
154	    {
155	      int noise = ((id * 3 + d * 5) % 21) - 10;   /* -10..+10 g */
156	      int g = daily_g + noise;
157	      g_day_g[id][d] = g > 0 ? g : 0;
158	      g_day_m[id][d] = 2 + ((id + d) % 3);          /* 2..4 meals */
159	    }
160	}
161	
162	void velapaw_store_roll_day(void)
163	{
164	  for (int p = 0; p < VELAPAW_MAX_PETS; p++)
165	    {
166	      for (int d = 0; d < TODAY; d++)
167	        {
168	          g_day_g[p][d] = g_day_g[p][d + 1];
169	          g_day_m[p][d] = g_day_m[p][d + 1];
170	        }
171	      g_day_g[p][TODAY] = 0;
172	      g_day_m[p][TODAY] = 0;
173	    }
174	}
175	
176	void velapaw_store_set_bcs(velapaw_pet_id_t id, int bcs)
177	{
178	  if (valid(id))
179	    {
180	      g_bcs[id] = bcs;
181	    }
182	}
183	
184	int velapaw_store_get_bcs(velapaw_pet_id_t id)
185	{
186	  return valid(id) ? g_bcs[id] : -1;
187	}
