static void spi2_redsquare_probe(void)
{
  g_spi = esp32s3_spibus_initialize(2);
  syslog(LOG_ERR,"[wslcd] SPI2 probe: handle=%p\n", g_spi);
  if (g_spi == NULL) return;
  SPI_LOCK(g_spi,true);
  SPI_SETMODE(g_spi,SPIDEV_MODE0);
  SPI_SETBITS(g_spi,8);
  SPI_SETFREQUENCY(g_spi,40000000);
  /* window 0..99 x 0..99, then fill red via HARDWARE SPI */
  spi_cmd(0x2A);spi_dat(0);spi_dat(0);spi_dat(0);spi_dat(99);
  spi_cmd(0x2B);spi_dat(0);spi_dat(0);spi_dat(0);spi_dat(99);
  spi_cmd(0x2C);
  esp32s3_gpiowrite(PIN_DC,true);
  { uint8_t row[200]; int i; for(i=0;i<100;i++){row[2*i]=0xF8;row[2*i+1]=0x00;}
    for(i=0;i<100;i++) SPI_SNDBLOCK(g_spi,row,200); }
  SPI_LOCK(g_spi,false);
  syslog(LOG_ERR,"[wslcd] SPI2 probe: red square sent; observe 8s\n");
  up_mdelay(8000);            /* TEMP: observe red square before LVGL paints */
  /* restore MOSI/CLK to plain GPIO so the bit-bang lcd_dev still works */
  esp32s3_configgpio(PIN_MOSI,OUTPUT);
  esp32s3_configgpio(PIN_CLK,OUTPUT);
  esp32s3_configgpio(PIN_DC,OUTPUT);
  g_out=(*(volatile uint32_t *)REG_OUT)&~(MOSI_M|CLK_M|DC_M);
}

