static void wall_set_min(int minofday)   /* set clock to today at HH:MM */
{
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  if (minofday < 0) minofday += 1440;
  minofday %= 1440;
  ts.tv_sec  = (ts.tv_sec / 86400) * 86400 + (long)minofday * 60;
