struct pet_blob
{
  uint32_t magic;
  uint32_t version;
  uint32_t npets;
  struct velapaw_pet pets[VELAPAW_MAX_PETS];
};

static struct pet_blob g_blob;                    /* .bss (internal RAM) */
static uint8_t g_pet_flash_stack[8192];           /* internal-RAM stack */

struct pet_io { int write; int rc; };

static void *pet_flash_thread(void *arg)
{
  struct pet_io *io = (struct pet_io *)arg;
  if (io->write)
    {
      uint32_t len = (sizeof(g_blob) + 4095u) & ~4095u;   /* whole sectors */
      io->rc = spi_flash_erase_range(VELAPAW_PET_FLASH_OFF, len);
      if (io->rc >= 0)
        {
          io->rc = spi_flash_write(VELAPAW_PET_FLASH_OFF, &g_blob,
                                   sizeof(g_blob));
        }
    }
  else
    {
      io->rc = spi_flash_read(VELAPAW_PET_FLASH_OFF, &g_blob, sizeof(g_blob));
    }
  return NULL;
}

static int pet_flash_run(int write)
{
  struct pet_io io = { write, -1 };
  pthread_attr_t attr;
  pthread_t th;
  pthread_attr_init(&attr);
  pthread_attr_setstack(&attr, g_pet_flash_stack, sizeof(g_pet_flash_stack));
  if (pthread_create(&th, &attr, pet_flash_thread, &io) != 0)
    {
      pthread_attr_destroy(&attr);
      return -1;
    }
  pthread_join(th, NULL);
  pthread_attr_destroy(&attr);
  return io.rc;
}

