307	
308	/* % of today's ration eaten: today / daily_limit (0..100, since feeding stops
309	 * at the limit). 100% = ate its full daily allowance. */
310	static int pet_appetite_pct(velapaw_pet_id_t id, const struct velapaw_pet *p)
311	{
312	  int today = velapaw_store_today_total(id);
313	  int pct = (p->daily_limit_g > 0) ? today * 100 / p->daily_limit_g : 100;
314	  return (pct > 100) ? 100 : pct;   /* limit is a cap: never over 100% */
315	}
