317	/* appetite-drop alert: the last completed day was under half the daily limit. */
318	static int pet_alert_drop(velapaw_pet_id_t id, const struct velapaw_pet *p)
319	{
320	  int yesterday = velapaw_store_day_total(id, 1);
321	  return (p->daily_limit_g > 0 && yesterday * 2 < p->daily_limit_g) ? 1 : 0;
