754	  int alert = 0;
755	  int n = velapaw_identity_count();
756	  for (int i = 0; i < n; i++)
757	    {
758	      const struct velapaw_pet *p = velapaw_identity_get(i);
759	      if (p && pet_alert_drop(i, p))
