761	          alert = 1;
762	          break;
763	        }
764	    }
765	  if (g_bell)
766	    {
767	      lv_obj_set_style_text_color(g_bell,
768	                                  lv_color_hex(alert ? COL_UNK : COL_DIM), 0);
769	    }
770	}
