/* Index the rotor one pocket: sweep forward (drops a pocket at the outlet),
 * then back (refills the empty pocket from the hopper). */
static void rotor_index_one(void)
{
  servo_set_us(SERVO_STEP_US);
  nxsig_usleep(SERVO_MOVE_MS * 1000);
  servo_set_us(SERVO_HOME_US);
  nxsig_usleep(SERVO_MOVE_MS * 1000);
}

/* Dispense `grams` by indexing whole pockets (rounded to nearest). MUST NOT run
 * on the UI thread (it sleeps ~0.8s per pocket): the app calls this from a
 * detached worker thread -- see hal/feeder_servo.c. */
int board_feeder_dispense(int grams)
{
  int pockets;
  int i;

  if (grams <= 0) return -1;

  /* round to the nearest whole pocket; always give at least one */
  pockets = (grams + GRAMS_PER_POCKET / 2) / GRAMS_PER_POCKET;
  if (pockets < 1) pockets = 1;

  for (i = 0; i < pockets; i++)
    {
      rotor_index_one();
    }

  syslog(LOG_ERR, "[feeder] dispensed %d pocket(s) ~%dg (asked %dg)\n",
         pockets, pockets * GRAMS_PER_POCKET, grams);
  return 0;
}

