// ============================================================================
// VelaPaw - paddle-rotor feeder  (contest 2026, team 043)
//
//   hopper  ->  rotor housing  ->  chute  ->  bowl
//
// The rotor is a vaned wheel turning inside a round housing under the hopper.
// Each vane pocket holds a FIXED VOLUME, so the dose depends on how many
// pockets the servo indexes -- not on how long a gate is held open, and not on
// how full the hopper is. That is the whole point: a flap dispenses more when
// the hopper is heavy, which would quietly break the per-pet portion control
// the product is built on.
//
// The MG90S is a 180-degree servo, so the rotor cannot spin continuously. The
// firmware indexes ONE POCKET PER OSCILLATION: sweep forward 60 degrees (a full
// pocket travels to the outlet and drops), then sweep back (the empty pocket
// returns under the inlet and refills).  grams = pockets x GRAMS_PER_POCKET.
// Keep POCKETS here == ROTOR_POCKETS in the board file.
//
// PRINTING (PLA or PETG, 0.2mm layers, 3 perimeters):
//   part="rotor"       - lay flat, hub up. No supports.
//   part="housing"     - as oriented (bore vertical). No supports.
//   part="plate_servo" - flat. No supports.
//   part="plate_idle"  - flat, boss up. No supports.
//   part="hopper"      - as oriented (wide end down). No supports.
//   part="all"         - preview of the assembly (do NOT print this).
//
// AFTER PRINTING - calibrate once:
//   Fill the hopper, dispense a single pocket, weigh what lands in the bowl.
//   Put that number in GRAMS_PER_POCKET in the board file. Done -- portions are
//   then correct for the rest of the machine's life, at any hopper level.
// ============================================================================

part = "all";   // "all" | "rotor" | "housing" | "plate_servo" | "plate_idle" | "hopper"

// ---- geometry --------------------------------------------------------------
POCKETS      = 6;      // vanes; MUST match ROTOR_POCKETS in esp32s3_st7789.c
BORE_R       = 29;     // housing inner radius
ROTOR_R      = 28.4;   // rotor outer radius (0.6mm running clearance)
HUB_R        = 8;      // rotor hub radius
WIDTH        = 38;     // rotor axial width  -> pocket volume
VANE_T       = 3;      // vane thickness
WALL         = 3;      // housing wall
CLEAR        = 0.4;    // general print clearance

// Pocket volume = pi*(BORE_R^2 - HUB_R^2)/POCKETS * WIDTH
//   = pi*(29^2 - 8^2)/6 * 38 ~= 15.5 cm^3
// Dry kibble bulk density ~0.35 g/cm^3  ->  ~5 g per pocket.
// Bigger pockets: raise WIDTH (linear) or BORE_R (quadratic).

// ---- MG90S -----------------------------------------------------------------
// VERIFY THESE WITH CALIPERS ON YOUR OWN SERVO before printing the servo plate.
// Clone dimensions vary by a millimetre or two, and this is the only part where
// that matters.
SERVO_BODY_L = 23.0;   // along the shaft-to-tail axis
SERVO_BODY_W = 12.6;
SERVO_TAB_SPAN = 32.2; // tip-to-tip across the mounting flanges
SERVO_TAB_T  = 2.5;
SERVO_SCREW_D = 2.2;   // M2 self-tappers
SERVO_SCREW_SPAN = 27.8; // screw hole centre-to-centre
SERVO_SHAFT_DX = 5.9;  // shaft axis offset from the BODY centre, toward the front

HORN_R       = 9;      // round horn radius (recess in the rotor hub)
HORN_T       = 1.8;    // horn thickness
SPLINE_D     = 5.2;    // splined boss clearance hole

// ---- openings --------------------------------------------------------------
INLET_W      = 34;     // hopper feeds in through the top of the housing
OUTLET_W     = 34;     // kibble falls out of the bottom
MOUNT_SCREW_D = 3.4;   // M3 through-holes, plates -> housing
POST_R       = 4.5;

HOPPER_TOP_R = 45;     // funnel mouth
HOPPER_H     = 70;

$fn = 96;

// ============================================================================
// rotor
// ============================================================================
module rotor() {
    difference() {
        union() {
            cylinder(r = HUB_R, h = WIDTH);
            for (i = [0 : POCKETS - 1])
                rotate([0, 0, i * 360 / POCKETS])
                    translate([-VANE_T / 2, 0, 0])
                        cube([VANE_T, ROTOR_R, WIDTH]);
        }

        // servo horn recess in the driven face (bottom)
        translate([0, 0, -0.1]) cylinder(r = HORN_R + CLEAR, h = HORN_T + 0.1);
        translate([0, 0, -0.1]) cylinder(d = SPLINE_D + CLEAR, h = 6);
        // two horn screws
        for (a = [0, 180])
            rotate([0, 0, a]) translate([6, 0, -0.1])
                cylinder(d = 2.0, h = 8);

        // stub-axle socket in the idle face (top)
        translate([0, 0, WIDTH - 8])
            cylinder(d = 6 + CLEAR * 2, h = 8.1);
    }
}

// ============================================================================
// housing: the drum the rotor turns inside, open at both ends.
// Printed standing on the flange, so the bore is vertical -> no supports. The
// inlet/outlet are cut in the vertical wall; a 45-degree roof over each keeps
// them bridge-free.
// ============================================================================
module housing() {
    difference() {
        union() {
            cylinder(r = BORE_R + WALL, h = WIDTH + 2 * 2);   // +2mm flange each end
            // screw posts
            for (a = [45, 135, 225, 315])
                rotate([0, 0, a])
                    translate([BORE_R + WALL - 1, 0, 0])
                        cylinder(r = POST_R, h = WIDTH + 4);
        }

        // the bore
        translate([0, 0, 2]) cylinder(r = BORE_R, h = WIDTH + 0.2);

        // inlet (top of the drum, +Y) and outlet (bottom, -Y), cut through the
        // wall with a chamfered roof so they print without support
        for (s = [1, -1])
            translate([-INLET_W / 2, s * (BORE_R - 1), 2])
                rotate([0, 0, 0])
                    cube([INLET_W, WALL + 4, WIDTH]);

        // plate screw holes
        for (a = [45, 135, 225, 315])
            rotate([0, 0, a])
                translate([BORE_R + WALL - 1, 0, -0.1])
                    cylinder(d = MOUNT_SCREW_D, h = WIDTH + 4.2);
    }
}

// ============================================================================
// end plates
// ============================================================================
module plate_blank() {
    difference() {
        cylinder(r = BORE_R + WALL + 2, h = 4);
        for (a = [45, 135, 225, 315])
            rotate([0, 0, a])
                translate([BORE_R + WALL - 1, 0, -0.1])
                    cylinder(d = MOUNT_SCREW_D, h = 4.2);
    }
}

// Servo plate. The servo body drops through the pocket; its flange screws to
// the plate face. The rotor axis sits on the SHAFT, which is offset from the
// body centre -- so the body pocket is shifted by -SERVO_SHAFT_DX to bring the
// shaft onto the plate centre (= the rotor axis).
module plate_servo() {
    difference() {
        plate_blank();

        translate([-SERVO_SHAFT_DX, 0, 0]) {
            // body pocket, through
            translate([-SERVO_BODY_L / 2, -SERVO_BODY_W / 2, -0.1])
                cube([SERVO_BODY_L + CLEAR, SERVO_BODY_W + CLEAR, 4.2]);
            // flange recess so the servo sits flush
            translate([-SERVO_TAB_SPAN / 2, -SERVO_BODY_W / 2, 4 - SERVO_TAB_T])
                cube([SERVO_TAB_SPAN + CLEAR, SERVO_BODY_W + CLEAR, SERVO_TAB_T + 0.1]);
            // mounting screws
            for (x = [-SERVO_SCREW_SPAN / 2, SERVO_SCREW_SPAN / 2])
                translate([x, 0, -0.1])
                    cylinder(d = SERVO_SCREW_D, h = 4.2);
        }
    }
}

// Idle plate: a plain stub axle for the far end of the rotor.
module plate_idle() {
    union() {
        plate_blank();
        translate([0, 0, 4]) cylinder(d = 6, h = 7);
    }
}

// ============================================================================
// hopper: a funnel that drops onto the inlet
// ============================================================================
module hopper() {
    difference() {
        union() {
            cylinder(r1 = INLET_W / 2 + WALL, r2 = HOPPER_TOP_R + WALL, h = HOPPER_H);
            // spigot that plugs into the housing inlet
            translate([0, 0, -8]) cylinder(r = INLET_W / 2 + WALL, h = 8);
        }
        translate([0, 0, -8.1])
            cylinder(r1 = INLET_W / 2 - CLEAR, r2 = INLET_W / 2 - CLEAR, h = 8.2);
        translate([0, 0, -0.1])
            cylinder(r1 = INLET_W / 2 - CLEAR, r2 = HOPPER_TOP_R, h = HOPPER_H + 0.2);
    }
}

// ============================================================================
// assembly preview
// ============================================================================
module assembly() {
    color("SlateGray")  housing();
    color("Goldenrod")  translate([0, 0, 2]) rotor();
    color("SteelBlue")  translate([0, 0, WIDTH + 4]) plate_idle();
    color("IndianRed")  translate([0, 0, -4]) plate_servo();
    color("Silver")     translate([0, BORE_R + 6, WIDTH / 2 + 2])
                            rotate([-90, 0, 0]) hopper();
}

if      (part == "rotor")       rotor();
else if (part == "housing")     housing();
else if (part == "plate_servo") plate_servo();
else if (part == "plate_idle")  plate_idle();
else if (part == "hopper")      hopper();
else                            assembly();

