  $r = Invoke-WebRequest -Uri "http://${vm}:8000$dst" -Method PUT -InFile "D:\openVela\spi-lcd-lab\ui_lvgl.c" -TimeoutSec 20 -UseBasicParsing
  "PUT ui_lvgl.c -> $($r.StatusCode) ($((Get-Item 'D:\openVela\spi-lcd-lab\ui_lvgl.c').Length) bytes)"
