$out = "$env:TEMP\nuttx-circle.bin"
try {
  Invoke-WebRequest -Uri "http://192.168.160.128:8000/nuttx.bin" -OutFile $out -TimeoutSec 20 -UseBasicParsing
  "downloaded: $((Get-Item $out).Length) bytes (built $((Get-Item $out).LastWriteTime))"
} catch { "download FAILED: $($_.Exception.Message)"; exit 1 }
python -m esptool --chip esp32s3 --port COM3 --baud 921600 write-flash 0x0 $out 2>&1 | Select-Object -Last 4

$vm = "192.168.160.128"
$dst = "D:\openVela\contest2026_043_CircuitForge\docs\esp-nn\kernels"
New-Item -ItemType Directory -Force -Path $dst | Out-Null
$wrappers = @("add","conv","depthwise_conv","fully_connected","mul","pooling","softmax")
foreach ($w in $wrappers) {
  try {
    Invoke-WebRequest -Uri "http://${vm}:8000/$w.cc" -OutFile "$dst\$w.cc" -TimeoutSec 15 -UseBasicParsing
    "pulled $w.cc ($((Get-Item "$dst\$w.cc").Length) bytes)"
  } catch { "FAILED $w.cc: $($_.Exception.Message)" }
}

